window.DHAMMAPADA_VERSES = [
 {
  "num": 1,
  "pali": "Manopubbaṅgamā dhammā,\nmanoseṭṭhā manomayā;\nManasā ce paduṭṭhena,\nbhāsati vā karoti vā;\nTato naṁ dukkhamanveti,\ncakkaṁva vahato padaṁ.",
  "english": "Intention is the leader of things;\nintention is first, they’re made by intention.\nIf with corrupt intent\nyou speak or act,\nsuffering follows you,\nlike a wheel, the ox’s foot."
 },
 {
  "num": 2,
  "pali": "Manopubbaṅgamā dhammā,\nmanoseṭṭhā manomayā;\nManasā ce pasannena,\nbhāsati vā karoti vā;\nTato naṁ sukhamanveti,\nchāyāva anapāyinī.",
  "english": "Intention is the leader of things;\nintention is first, they’re made by intention.\nIf with pure intent\nyou speak or act,\nhappiness follows you\nlike a shadow that never leaves."
 },
 {
  "num": 3,
  "pali": "Akkocchi maṁ avadhi maṁ,\najini maṁ ahāsi me;\nYe ca taṁ upanayhanti,\nveraṁ tesaṁ na sammati.",
  "english": "“They abused me, they hit me!\nThey beat me, they robbed me!”\nFor those who bear such a grudge,\nhatred is never laid to rest."
 },
 {
  "num": 4,
  "pali": "Akkocchi maṁ avadhi maṁ,\najini maṁ ahāsi me;\nYe ca taṁ nupanayhanti,\nveraṁ tesūpasammati.",
  "english": "“They abused me, they hit me!\nThey beat me, they robbed me!”\nFor those who bear no such grudge,\nhatred is laid to rest."
 },
 {
  "num": 5,
  "pali": "Na hi verena verāni,\nsammantīdha kudācanaṁ;\nAverena ca sammanti,\nesa dhammo sanantano.",
  "english": "For never is hatred\nlaid to rest by hate,\nit’s laid to rest by love:\nthis is an ancient teaching."
 },
 {
  "num": 6,
  "pali": "Pare ca na vijānanti,\nmayamettha yamāmase;\nYe ca tattha vijānanti,\ntato sammanti medhagā.",
  "english": "When others do not understand,\nlet us, who do understand this,\nrestrain ourselves in this regard;\nfor that is how conflicts are laid to rest."
 },
 {
  "num": 7,
  "pali": "Subhānupassiṁ viharantaṁ,\nindriyesu asaṁvutaṁ;\nBhojanamhi cāmattaññuṁ,\nkusītaṁ hīnavīriyaṁ;\nTaṁ ve pasahati māro,\nvāto rukkhaṁva dubbalaṁ.",
  "english": "Those who contemplate the beautiful,\ntheir faculties unrestrained,\nimmoderate in eating,\nlazy, lacking energy:\nMāra strikes them down\nlike the wind, a feeble tree."
 },
 {
  "num": 8,
  "pali": "Asubhānupassiṁ viharantaṁ,\nIndriyesu susaṁvutaṁ;\nBhojanamhi ca mattaññuṁ,\nSaddhaṁ āraddhavīriyaṁ;\nTaṁ ve nappasahati māro,\nVāto selaṁva pabbataṁ.",
  "english": "Those who contemplate the ugly,\ntheir faculties well-restrained,\neating in moderation,\nfaithful and energetic:\nMāra cannot strike them down,\nlike the wind, a rocky mountain."
 },
 {
  "num": 9,
  "pali": "Anikkasāvo kāsāvaṁ,\nyo vatthaṁ paridahissati;\nApeto damasaccena,\nna so kāsāvamarahati.",
  "english": "One who, not free of stains themselves,\nwould wear the robe stained in ocher,\nbereft of self-control and truth:\nthey are not worthy of the ocher robe."
 },
 {
  "num": 10,
  "pali": "Yo ca vantakasāvassa,\nsīlesu susamāhito;\nUpeto damasaccena,\nsa ve kāsāvamarahati.",
  "english": "One who’s purged all their stains,\nsteady in ethics,\npossessed of self-control and of truth,\nthey are truly worthy of the ocher robe."
 },
 {
  "num": 11,
  "pali": "Asāre sāramatino,\nsāre cāsāradassino;\nTe sāraṁ nādhigacchanti,\nmicchāsaṅkappagocarā.",
  "english": "Thinking the inessential is essential,\nseeing the essential as inessential;\nthey don’t realize the essential,\nfor wrong thoughts are their habitat."
 },
 {
  "num": 12,
  "pali": "Sārañca sārato ñatvā,\nasārañca asārato;\nTe sāraṁ adhigacchanti,\nsammāsaṅkappagocarā.",
  "english": "Having known the essential as essential,\nand the inessential as inessential;\nthey realize the essential,\nfor right thoughts are their habitat."
 },
 {
  "num": 13,
  "pali": "Yathā agāraṁ ducchannaṁ,\nvuṭṭhī samativijjhati;\nEvaṁ abhāvitaṁ cittaṁ,\nrāgo samativijjhati.",
  "english": "Just as rain seeps into\na poorly roofed house,\nlust seeps into\nan undeveloped mind."
 },
 {
  "num": 14,
  "pali": "Yathā agāraṁ suchannaṁ,\nvuṭṭhī na samativijjhati;\nEvaṁ subhāvitaṁ cittaṁ,\nrāgo na samativijjhati.",
  "english": "Just as rain doesn’t seep into\na well roofed house,\nlust doesn’t seep into\na well developed mind."
 },
 {
  "num": 15,
  "pali": "Idha socati pecca socati,\nPāpakārī ubhayattha socati;\nSo socati so vihaññati,\nDisvā kammakiliṭṭhamattano.",
  "english": "Here they grieve, hereafter they grieve,\nan evildoer grieves in both places.\nThey grieve and fret,\nseeing their own corrupt deeds."
 },
 {
  "num": 16,
  "pali": "Idha modati pecca modati,\nKatapuñño ubhayattha modati;\nSo modati so pamodati,\nDisvā kammavisuddhimattano.",
  "english": "Here they rejoice, hereafter they rejoice,\none who does good rejoices in both places.\nThey rejoice and celebrate,\nseeing their own pure deeds."
 },
 {
  "num": 17,
  "pali": "Idha tappati pecca tappati,\nPāpakārī ubhayattha tappati;\n“Pāpaṁ me katan”ti tappati,\nBhiyyo tappati duggatiṁ gato.",
  "english": "Here they’re tormented, <j>hereafter they’re tormented,\nan evildoer is tormented in both places.\nThey’re tormented <j>thinking of bad things they’ve done;\nwhen gone to a bad place, <j>they’re tormented all the more."
 },
 {
  "num": 18,
  "pali": "Idha nandati pecca nandati,\nKatapuñño ubhayattha nandati;\n“Puññaṁ me katan”ti nandati,\nBhiyyo nandati suggatiṁ gato.",
  "english": "Here they delight, hereafter they delight,\none who does good delights in both places.\nThey delight thinking of good things they’ve done;\nwhen gone to a good place, they delight all the more."
 },
 {
  "num": 19,
  "pali": "Bahumpi ce saṁhita bhāsamāno,\nNa takkaro hoti naro pamatto;\nGopova gāvo gaṇayaṁ paresaṁ,\nNa bhāgavā sāmaññassa hoti.",
  "english": "Much though they may recite scripture,\nif a negligent person does not apply them,\nthen, like a cowherd who counts the cattle of others,\nthey miss out on the blessings of the ascetic life."
 },
 {
  "num": 20,
  "pali": "Appampi ce saṁhita bhāsamāno,\nDhammassa hoti anudhammacārī;\nRāgañca dosañca pahāya mohaṁ,\nSammappajāno suvimuttacitto;\nAnupādiyāno idha vā huraṁ vā,\nSa bhāgavā sāmaññassa hoti.",
  "english": "Little though they may recite scripture,\nif they live in line with the teaching,\nhaving given up greed, hate, and delusion,\nwith deep understanding and heart well freed,\nnot grasping to this life or the next,\nthey share in the blessings of the ascetic life."
 },
 {
  "num": 21,
  "pali": "Appamādo amatapadaṁ,\npamādo maccuno padaṁ;\nAppamattā na mīyanti,\nye pamattā yathā matā.",
  "english": "Heedfulness is the state free of death;\nheedlessness is the state of death.\nThe heedful do not die,\nwhile the heedless are like the dead."
 },
 {
  "num": 22,
  "pali": "Evaṁ visesato ñatvā,\nappamādamhi paṇḍitā;\nAppamāde pamodanti,\nariyānaṁ gocare ratā.",
  "english": "Understanding this distinction\nwhen it comes to heedfulness,\nthe astute rejoice in heedfulness,\nhappy in the noble ones’ domain."
 },
 {
  "num": 23,
  "pali": "Te jhāyino sātatikā,\nniccaṁ daḷhaparakkamā;\nPhusanti dhīrā nibbānaṁ,\nyogakkhemaṁ anuttaraṁ.",
  "english": "They who regularly meditate,\nalways staunchly vigorous;\nthe attentive realize extinguishment,\nthe supreme sanctuary from the yoke."
 },
 {
  "num": 24,
  "pali": "Uṭṭhānavato satīmato,\nSucikammassa nisammakārino;\nSaññatassa dhammajīvino,\nAppamattassa yasobhivaḍḍhati.",
  "english": "For the hard-working and mindful,\npure of deed and attentive,\nrestrained, living righteously, and diligent,\ntheir reputation only grows."
 },
 {
  "num": 25,
  "pali": "Uṭṭhānenappamādena,\nsaṁyamena damena ca;\nDīpaṁ kayirātha medhāvī,\nyaṁ ogho nābhikīrati.",
  "english": "By hard work and diligence,\nby restraint and by self-control,\na smart person would build an island\nthat the floods cannot overflow."
 },
 {
  "num": 26,
  "pali": "Pamādamanuyuñjanti,\nbālā dummedhino janā;\nAppamādañca medhāvī,\ndhanaṁ seṭṭhaṁva rakkhati.",
  "english": "Fools and simpletons\ndevote themselves to negligence.\nBut the wise protect diligence\nas their best treasure."
 },
 {
  "num": 27,
  "pali": "Mā pamādamanuyuñjetha,\nmā kāmaratisanthavaṁ;\nAppamatto hi jhāyanto,\npappoti vipulaṁ sukhaṁ.",
  "english": "Don’t devote yourself to negligence,\nor delight in erotic intimacy.\nFor if you’re diligent and meditate,\nyou’ll attain abundant happiness."
 },
 {
  "num": 28,
  "pali": "Pamādaṁ appamādena,\nyadā nudati paṇḍito;\nPaññāpāsādamāruyha,\nasoko sokiniṁ pajaṁ;\nPabbataṭṭhova bhūmaṭṭhe,\ndhīro bāle avekkhati.",
  "english": "When the astute dispel negligence\nby means of diligence,\nascending the palace of wisdom,\nsorrowless, they behold this generation of sorrow,\nas an attentive one on a mountain top\nbeholds the fools below."
 },
 {
  "num": 29,
  "pali": "Appamatto pamattesu,\nsuttesu bahujāgaro;\nAbalassaṁva sīghasso,\nhitvā yāti sumedhaso.",
  "english": "Heedful among the heedless,\nwide awake while others sleep—\na true sage leaves them behind,\nlike a swift horse passing a feeble."
 },
 {
  "num": 30,
  "pali": "Appamādena maghavā,\ndevānaṁ seṭṭhataṁ gato;\nAppamādaṁ pasaṁsanti,\npamādo garahito sadā.",
  "english": "Maghavā became chief of the gods\nby means of diligence.\nPeople praise diligence,\nwhile negligence is always deplored."
 },
 {
  "num": 31,
  "pali": "Appamādarato bhikkhu,\npamāde bhayadassi vā;\nSaṁyojanaṁ aṇuṁ thūlaṁ,\nḍahaṁ aggīva gacchati.",
  "english": "A mendicant who loves diligence,\nseeing fear in negligence—\nadvances like fire,\nburning up fetters big and small."
 },
 {
  "num": 32,
  "pali": "Appamādarato bhikkhu,\npamāde bhayadassi vā;\nAbhabbo parihānāya,\nnibbānasseva santike.",
  "english": "A mendicant who loves diligence,\nseeing fear in negligence—\nsuch a one can’t decline,\nand has drawn near to extinguishment."
 },
 {
  "num": 33,
  "pali": "Phandanaṁ capalaṁ cittaṁ,\ndūrakkhaṁ dunnivārayaṁ;\nUjuṁ karoti medhāvī,\nusukārova tejanaṁ.",
  "english": "The mind quivers and quakes,\nhard to guard, hard to curb.\nThe discerning straighten it out,\nlike a fletcher an arrow."
 },
 {
  "num": 34,
  "pali": "Vārijova thale khitto,\nokamokataubbhato;\nPariphandatidaṁ cittaṁ,\nmāradheyyaṁ pahātave.",
  "english": "Like a fish pulled from the sea\nand cast upon the shore,\nthis mind flounders about,\ntrying to throw off Māra’s dominion."
 },
 {
  "num": 35,
  "pali": "Dunniggahassa lahuno,\nyatthakāmanipātino;\nCittassa damatho sādhu,\ncittaṁ dantaṁ sukhāvahaṁ.",
  "english": "Hard to hold back, flighty,\nalighting where it will;\nit’s good to tame the mind;\na tamed mind leads to bliss."
 },
 {
  "num": 36,
  "pali": "Sududdasaṁ sunipuṇaṁ,\nyatthakāmanipātinaṁ;\nCittaṁ rakkhetha medhāvī,\ncittaṁ guttaṁ sukhāvahaṁ.",
  "english": "So hard to see, so subtle,\nalighting where it will;\nthe discerning protect the mind,\na guarded mind leads to bliss."
 },
 {
  "num": 37,
  "pali": "Dūraṅgamaṁ ekacaraṁ,\nasarīraṁ guhāsayaṁ;\nYe cittaṁ saṁyamissanti,\nmokkhanti mārabandhanā.",
  "english": "The mind travels far, wandering alone;\nincorporeal, it lies hidden in the heart.\nThose who will restrain the mind\nare freed from Māra’s bonds."
 },
 {
  "num": 38,
  "pali": "Anavaṭṭhitacittassa,\nsaddhammaṁ avijānato;\nPariplavapasādassa,\npaññā na paripūrati.",
  "english": "Those of unsteady mind,\nwho don’t understand the true teaching,\nand whose confidence wavers,\ndo not perfect their wisdom."
 },
 {
  "num": 39,
  "pali": "Anavassutacittassa,\nananvāhatacetaso;\nPuññapāpapahīnassa,\nnatthi jāgarato bhayaṁ.",
  "english": "One whose mind is not festering,\nwhose heart is undamaged,\nwho’s given up right and wrong,\nalert, has nothing to fear."
 },
 {
  "num": 40,
  "pali": "Kumbhūpamaṁ kāyamimaṁ viditvā,\nNagarūpamaṁ cittamidaṁ ṭhapetvā;\nYodhetha māraṁ paññāvudhena,\nJitañca rakkhe anivesano siyā.",
  "english": "Knowing this body breaks like a pot,\nand fortifying the mind like a citadel,\nattack Māra with the sword of wisdom,\nguard your conquest, and never settle."
 },
 {
  "num": 41,
  "pali": "Aciraṁ vatayaṁ kāyo,\npathaviṁ adhisessati;\nChuddho apetaviññāṇo,\nniratthaṁva kaliṅgaraṁ.",
  "english": "All too soon this body\nwill lie upon the earth,\nbereft of consciousness,\ntossed aside like a worthless log."
 },
 {
  "num": 42,
  "pali": "Diso disaṁ yaṁ taṁ kayirā,\nverī vā pana verinaṁ;\nMicchāpaṇihitaṁ cittaṁ,\npāpiyo naṁ tato kare.",
  "english": "A wrongly directed mind\nwould do you more harm\nthan a hater to the hated,\nor an enemy to their foe."
 },
 {
  "num": 43,
  "pali": "Na taṁ mātā pitā kayirā,\naññe vāpi ca ñātakā;\nSammāpaṇihitaṁ cittaṁ,\nseyyaso naṁ tato kare.",
  "english": "A rightly directed mind\nwould do you more good\nthan your mother or father\nor any other relative."
 },
 {
  "num": 44,
  "pali": "Ko imaṁ pathaviṁ vicessati,\nYamalokañca imaṁ sadevakaṁ;\nKo dhammapadaṁ sudesitaṁ,\nKusalo pupphamiva pacessati.",
  "english": "Who bestirs this earth,\nand the Yama realm with its gods?\nWho sets out the well-taught word of truth,\nas an expert a flower?"
 },
 {
  "num": 45,
  "pali": "Sekho pathaviṁ vicessati,\nYamalokañca imaṁ sadevakaṁ;\nSekho dhammapadaṁ sudesitaṁ,\nKusalo pupphamiva pacessati.",
  "english": "A trainee bestirs this earth,\nand the Yama realm with its gods.\nA trainee sets out the well-taught word of truth,\nas an expert a flower."
 },
 {
  "num": 46,
  "pali": "Pheṇūpamaṁ kāyamimaṁ viditvā,\nMarīcidhammaṁ abhisambudhāno;\nChetvāna mārassa papupphakāni,\nAdassanaṁ maccurājassa gacche.",
  "english": "Knowing this body’s like foam,\nrealizing it’s all just a mirage,\nand cutting off Māra’s blossoming,\nvanish from the King of Death."
 },
 {
  "num": 47,
  "pali": "Pupphāni heva pacinantaṁ,\nbyāsattamanasaṁ naraṁ;\nSuttaṁ gāmaṁ mahoghova,\nmaccu ādāya gacchati.",
  "english": "As a mighty flood sweeps off a sleeping village,\ndeath steals away a man\neven as he gathers flowers,\nhis mind caught up in them."
 },
 {
  "num": 48,
  "pali": "Pupphāni heva pacinantaṁ,\nbyāsattamanasaṁ naraṁ;\nAtittaññeva kāmesu,\nantako kurute vasaṁ.",
  "english": "The terminator gains control of the man\nwho has not had his fill of pleasures,\neven as he gathers flowers,\nhis mind caught up in them."
 },
 {
  "num": 49,
  "pali": "Yathāpi bhamaro pupphaṁ,\nvaṇṇagandhamaheṭhayaṁ;\nPaleti rasamādāya,\nevaṁ gāme munī care.",
  "english": "A bee takes the nectar\nand moves on, doing no damage\nto the flower’s beauty and fragrance;\nand that’s how a sage should walk in the village."
 },
 {
  "num": 50,
  "pali": "Na paresaṁ vilomāni,\nna paresaṁ katākataṁ;\nAttanova avekkheyya,\nkatāni akatāni ca.",
  "english": "Don’t find fault with others,\nwith what they’ve done or left undone.\nYou should only watch yourself,\nwhat you’ve done or left undone."
 },
 {
  "num": 51,
  "pali": "Yathāpi ruciraṁ pupphaṁ,\nvaṇṇavantaṁ agandhakaṁ;\nEvaṁ subhāsitā vācā,\naphalā hoti akubbato.",
  "english": "Just like a glorious flower\nthat’s colorful but lacks fragrance;\neloquent speech is fruitless\nfor one who does not act on it."
 },
 {
  "num": 52,
  "pali": "Yathāpi ruciraṁ pupphaṁ,\nVaṇṇavantaṁ sagandhakaṁ;\nEvaṁ subhāsitā vācā,\nSaphalā hoti kubbato.",
  "english": "Just like a glorious flower\nthat’s both colorful and fragrant,\neloquent speech is fruitful\nfor one who acts on it."
 },
 {
  "num": 53,
  "pali": "Yathāpi puppharāsimhā,\nkayirā mālāguṇe bahū;\nEvaṁ jātena maccena,\nkattabbaṁ kusalaṁ bahuṁ.",
  "english": "Just as one would create many garlands\nfrom a heap of flowers,\nwhen a person has come to be born,\nthey should do many skillful things."
 },
 {
  "num": 54,
  "pali": "Na pupphagandho paṭivātameti,\nNa candanaṁ tagaramallikā vā;\nSatañca gandho paṭivātameti,\nSabbā disā sappuriso pavāyati.",
  "english": "The fragrance of flowers doesn’t spread upwind,\nnor sandalwood, pinwheel, or jasmine;\nbut the fragrance of the good spreads upwind;\na true person’s virtue spreads in every direction."
 },
 {
  "num": 55,
  "pali": "Candanaṁ tagaraṁ vāpi,\nuppalaṁ atha vassikī;\nEtesaṁ gandhajātānaṁ,\nsīlagandho anuttaro.",
  "english": "Among all the fragrances—\nsandalwood or pinwheel\nor lotus or jasmine—\nthe fragrance of virtue is supreme."
 },
 {
  "num": 56,
  "pali": "Appamatto ayaṁ gandho,\nyāyaṁ tagaracandanī;\nYo ca sīlavataṁ gandho,\nvāti devesu uttamo.",
  "english": "Faint is the fragrance\nof sandal or pinwheel;\nbut the fragrance of the virtuous\nfloats to the highest gods."
 },
 {
  "num": 57,
  "pali": "Tesaṁ sampannasīlānaṁ,\nappamādavihārinaṁ;\nSammadaññāvimuttānaṁ,\nmāro maggaṁ na vindati.",
  "english": "For those accomplished in ethics,\nmeditating diligently,\nfreed through the highest knowledge,\nMāra cannot find their path."
 },
 {
  "num": 58,
  "pali": "Yathā saṅkāradhānasmiṁ,\nujjhitasmiṁ mahāpathe;\nPadumaṁ tattha jāyetha,\nsucigandhaṁ manoramaṁ.",
  "english": "From a heap of trash\ndiscarded on the highway,\na lotus might blossom,\nfragrant and delightful."
 },
 {
  "num": 59,
  "pali": "Evaṁ saṅkārabhūtesu,\nandhabhūte puthujjane;\nAtirocati paññāya,\nsammāsambuddhasāvako.",
  "english": "So too, among those thought of as trash,\na disciple of the perfect Buddha\noutshines with their wisdom\nthe blind ordinary folk."
 },
 {
  "num": 60,
  "pali": "Dīghā jāgarato ratti,\ndīghaṁ santassa yojanaṁ;\nDīgho bālāna saṁsāro,\nsaddhammaṁ avijānataṁ.",
  "english": "Long is the night for the wakeful;\nlong is the league for the weary;\nlong transmigrate the fools\nwho don’t understand the true teaching."
 },
 {
  "num": 61,
  "pali": "Carañce nādhigaccheyya,\nSeyyaṁ sadisamattano;\nEkacariyaṁ daḷhaṁ kayirā,\nNatthi bāle sahāyatā.",
  "english": "If while wandering you find no partner\nequal or better than yourself,\nthen firmly resolve to wander alone—\nthere’s no fellowship with fools."
 },
 {
  "num": 62,
  "pali": "Puttā matthi dhanaṁ matthi,\niti bālo vihaññati;\nAttā hi attano natthi,\nkuto puttā kuto dhanaṁ.",
  "english": "“Sons are mine, wealth is mine”—\nthus the fool frets.\nFor even your self is not your own,\nlet alone your sons or wealth."
 },
 {
  "num": 63,
  "pali": "Yo bālo maññati bālyaṁ,\npaṇḍito vāpi tena so;\nBālo ca paṇḍitamānī,\nsa ve “bālo”ti vuccati.",
  "english": "The fool who thinks they’re a fool\nis wise at least to that extent.\nBut the true fool is said to be one\nwho imagines that they are wise."
 },
 {
  "num": 64,
  "pali": "Yāvajīvampi ce bālo,\npaṇḍitaṁ payirupāsati;\nNa so dhammaṁ vijānāti,\ndabbī sūparasaṁ yathā.",
  "english": "Though a fool attends to the wise\neven for the rest of their life,\nthey still don’t understand the teaching,\nlike a spoon the taste of the soup."
 },
 {
  "num": 65,
  "pali": "Muhuttamapi ce viññū,\npaṇḍitaṁ payirupāsati;\nKhippaṁ dhammaṁ vijānāti,\njivhā sūparasaṁ yathā.",
  "english": "If a clever person attends to the wise\neven just for an hour or so,\nthey swiftly understand the teaching,\nlike a tongue the taste of the soup."
 },
 {
  "num": 66,
  "pali": "Caranti bālā dummedhā,\namitteneva attanā;\nKarontā pāpakaṁ kammaṁ,\nyaṁ hoti kaṭukapphalaṁ.",
  "english": "Fools and simpletons behave\nlike their own worst enemies,\ndoing wicked deeds\nthat ripen as bitter fruit."
 },
 {
  "num": 67,
  "pali": "Na taṁ kammaṁ kataṁ sādhu,\nyaṁ katvā anutappati;\nYassa assumukho rodaṁ,\nvipākaṁ paṭisevati.",
  "english": "It’s not good to do a deed\nthat plagues you later on,\nfor which you weep and wail,\nas its effect stays with you."
 },
 {
  "num": 68,
  "pali": "Tañca kammaṁ kataṁ sādhu,\nyaṁ katvā nānutappati;\nYassa patīto sumano,\nvipākaṁ paṭisevati.",
  "english": "It is good to do a deed\nthat doesn’t plague you later on,\nthat gladdens and cheers,\nas its effect stays with you."
 },
 {
  "num": 69,
  "pali": "Madhuṁvā maññati bālo,\nyāva pāpaṁ na paccati;\nYadā ca paccati pāpaṁ,\natha dukkhaṁ nigacchati.",
  "english": "The fool imagines that evil is sweet,\nso long as it has not yet ripened.\nBut as soon as that evil ripens,\nthey fall into suffering."
 },
 {
  "num": 70,
  "pali": "Māse māse kusaggena,\nbālo bhuñjeyya bhojanaṁ;\nNa so saṅkhātadhammānaṁ,\nkalaṁ agghati soḷasiṁ.",
  "english": "Month after month a fool may eat\nfood from a grass-blade’s tip;\nbut they’ll never be worth a sixteenth part\nof one who has appraised the teaching."
 },
 {
  "num": 71,
  "pali": "Na hi pāpaṁ kataṁ kammaṁ,\nSajjukhīraṁva muccati;\nḌahantaṁ bālamanveti,\nBhasmacchannova pāvako.",
  "english": "For a wicked deed that has been done\ndoes not curdle quickly like milk.\nSmoldering, it follows the fool,\nlike a fire smothered over with ash."
 },
 {
  "num": 72,
  "pali": "Yāvadeva anatthāya,\nñattaṁ bālassa jāyati;\nHanti bālassa sukkaṁsaṁ,\nmuddhamassa vipātayaṁ.",
  "english": "Whatever fame a fool may get,\nit only gives rise to harm.\nWhatever good features they have it ruins,\nand blows their head into bits."
 },
 {
  "num": 73,
  "pali": "Asantaṁ bhāvanamiccheyya,\nPurekkhārañca bhikkhusu;\nĀvāsesu ca issariyaṁ,\nPūjaṁ parakulesu ca.",
  "english": "They’d seek the esteem that they lack,\nand status among the mendicants;\nauthority over monasteries,\nand honor among other families."
 },
 {
  "num": 74,
  "pali": "Mameva kata maññantu,\ngihī pabbajitā ubho;\nMamevātivasā assu,\nkiccākiccesu kismici;\nIti bālassa saṅkappo,\nicchā māno ca vaḍḍhati.",
  "english": "“Let both layfolk and renunciants think\nthe work was done by me alone.\nIn anything at all that’s to be done,\nlet them fall under my sway alone.”\nSo thinks the fool,\ntheir greed and pride only growing."
 },
 {
  "num": 75,
  "pali": "Aññā hi lābhūpanisā,\naññā nibbānagāminī;\nEvametaṁ abhiññāya,\nbhikkhu buddhassa sāvako;\nSakkāraṁ nābhinandeyya,\nvivekamanubrūhaye.",
  "english": "For the means to profit and the path to quenching\nare two quite different things.\nA mendicant disciple of the Buddha,\nunderstanding what this really means,\nwould never delight in honors,\nbut rather would foster seclusion."
 },
 {
  "num": 76,
  "pali": "Nidhīnaṁva pavattāraṁ,\nyaṁ passe vajjadassinaṁ;\nNiggayhavādiṁ medhāviṁ,\ntādisaṁ paṇḍitaṁ bhaje;\nTādisaṁ bhajamānassa,\nseyyo hoti na pāpiyo.",
  "english": "Regard one who sees your faults\nas a guide to a hidden treasure.\nStay close to one so intelligent and astute\nwho curbs you when you need it.\nSticking close to such an impartial person,\nthings get better, not worse."
 },
 {
  "num": 77,
  "pali": "Ovadeyyānusāseyya,\nasabbhā ca nivāraye;\nSatañhi so piyo hoti,\nasataṁ hoti appiyo.",
  "english": "Advise and instruct;\ncurb wickedness:\nfor you shall be loved by the good,\nand disliked by the bad."
 },
 {
  "num": 78,
  "pali": "Na bhaje pāpake mitte,\nna bhaje purisādhame;\nBhajetha mitte kalyāṇe,\nbhajetha purisuttame.",
  "english": "Don’t mix with bad friends,\nnor with the worst of men.\nMix with spiritual friends,\nand with the best of men."
 },
 {
  "num": 79,
  "pali": "Dhammapīti sukhaṁ seti,\nvippasannena cetasā;\nAriyappavedite dhamme,\nsadā ramati paṇḍito.",
  "english": "Through joy in the teaching you sleep at ease,\nwith clear and confident heart.\nAn astute person always delights in the teaching\nproclaimed by the Noble One."
 },
 {
  "num": 80,
  "pali": "Udakañhi nayanti nettikā,\nUsukārā namayanti tejanaṁ;\nDāruṁ namayanti tacchakā,\nAttānaṁ damayanti paṇḍitā.",
  "english": "While irrigators guide water,\nfletchers bend arrows straight,\nand carpenters bend timber straight,\nthe astute tame themselves."
 },
 {
  "num": 81,
  "pali": "Selo yathā ekaghano,\nvātena na samīrati;\nEvaṁ nindāpasaṁsāsu,\nna samiñjanti paṇḍitā.",
  "english": "As the wind cannot stir\na solid mass of rock,\nso too blame and praise\ndo not affect the wise."
 },
 {
  "num": 82,
  "pali": "Yathāpi rahado gambhīro,\nvippasanno anāvilo;\nEvaṁ dhammāni sutvāna,\nvippasīdanti paṇḍitā.",
  "english": "Like a deep lake,\nclear and unclouded,\nso clear are the astute\nwhen they hear the teachings."
 },
 {
  "num": 83,
  "pali": "Sabbattha ve sappurisā cajanti,\nNa kāmakāmā lapayanti santo;\nSukhena phuṭṭhā atha vā dukhena,\nNa uccāvacaṁ paṇḍitā dassayanti.",
  "english": "True persons give up everything,\nthey don’t cajole for the things they desire.\nThough touched by sadness or happiness,\nthe astute appear neither depressed nor elated."
 },
 {
  "num": 84,
  "pali": "Na attahetu na parassa hetu,\nNa puttamicche na dhanaṁ na raṭṭhaṁ;\nNa iccheyya adhammena samiddhimattano,\nSa sīlavā paññavā dhammiko siyā.",
  "english": "Never wish for success by unjust means,\nfor your own sake or that of another,\ndesiring children, wealth, or nation;\nrather, be virtuous, wise, and just."
 },
 {
  "num": 85,
  "pali": "Appakā te manussesu,\nye janā pāragāmino;\nAthāyaṁ itarā pajā,\ntīramevānudhāvati.",
  "english": "Few are those among humans\nwho cross to the far shore.\nThe rest just run around\non the near shore."
 },
 {
  "num": 86,
  "pali": "Ye ca kho sammadakkhāte,\ndhamme dhammānuvattino;\nTe janā pāramessanti,\nmaccudheyyaṁ suduttaraṁ.",
  "english": "When the teaching is well explained,\nthe people who practice accordingly\nwill cross over\nDeath’s dominion so hard to pass."
 },
 {
  "num": 87,
  "pali": "Kaṇhaṁ dhammaṁ vippahāya,\nSukkaṁ bhāvetha paṇḍito;\nOkā anokamāgamma,\nViveke yattha dūramaṁ.",
  "english": "Rid of dark qualities,\nan astute person would develop the bright.\nHaving left home for homelessness\nin seclusion, where joy is hard,"
 },
 {
  "num": 88,
  "pali": "Tatrābhiratimiccheyya,\nhitvā kāme akiñcano;\nPariyodapeyya attānaṁ,\ncittaklesehi paṇḍito.",
  "english": "they’d long for satisfaction there.\nForsaking sensual pleasures, owning nothing,\nan astute person would cleanse themselves\nof mental corruptions."
 },
 {
  "num": 89,
  "pali": "Yesaṁ sambodhiyaṅgesu,\nsammā cittaṁ subhāvitaṁ;\nĀdānapaṭinissagge,\nanupādāya ye ratā;\nKhīṇāsavā jutimanto,\nte loke parinibbutā.",
  "english": "And those whose minds are rightly developed\nin the awakening factors;\nwho, letting go of attachments,\ndelight in not grasping:\nwith defilements ended, brilliant,\nthey are quenched in this world."
 },
 {
  "num": 90,
  "pali": "Gataddhino visokassa,\nvippamuttassa sabbadhi;\nSabbaganthappahīnassa,\npariḷāho na vijjati.",
  "english": "At journey’s end, rid of sorrow;\neverywhere free,\nall ties given up,\nno fever is found in them."
 },
 {
  "num": 91,
  "pali": "Uyyuñjanti satīmanto,\nna nikete ramanti te;\nHaṁsāva pallalaṁ hitvā,\nokamokaṁ jahanti te.",
  "english": "The mindful apply themselves;\nthey delight in no abode.\nLike a swan gone from the marsh,\nthey leave home after home behind."
 },
 {
  "num": 92,
  "pali": "Yesaṁ sannicayo natthi,\nye pariññātabhojanā;\nSuññato animitto ca,\nvimokkho yesaṁ gocaro;\nĀkāseva sakuntānaṁ,\ngati tesaṁ durannayā.",
  "english": "Those with nothing stored up,\nwho have understood their food,\nwhose domain is the liberation\nof the signless and the empty:\ntheir path is hard to trace,\nlike birds in the sky."
 },
 {
  "num": 93,
  "pali": "Yassāsavā parikkhīṇā,\nāhāre ca anissito;\nSuññato animitto ca,\nvimokkho yassa gocaro;\nĀkāseva sakuntānaṁ,\npadaṁ tassa durannayaṁ.",
  "english": "One whose defilements have ended;\nwho’s not attached to food;\nwhose domain is the liberation\nof the signless and the empty:\ntheir track is hard to trace,\nlike birds in the sky."
 },
 {
  "num": 94,
  "pali": "Yassindriyāni samathaṅgatāni,\nAssā yathā sārathinā sudantā;\nPahīnamānassa anāsavassa,\nDevāpi tassa pihayanti tādino.",
  "english": "Whose faculties have become serene,\nlike horses tamed by a charioteer,\nwho has abandoned conceit and defilements;\nthe unaffected one is envied by even the gods."
 },
 {
  "num": 95,
  "pali": "Pathavisamo no virujjhati,\nIndakhilupamo tādi subbato;\nRahadova apetakaddamo,\nSaṁsārā na bhavanti tādino.",
  "english": "Undisturbed like the earth,\ntrue to their vows, steady as Indra’s pillar,\nlike a lake clear of mud;\nsuch a one does not transmigrate."
 },
 {
  "num": 96,
  "pali": "Santaṁ tassa manaṁ hoti,\nsantā vācā ca kamma ca;\nSammadaññāvimuttassa,\nupasantassa tādino.",
  "english": "Their mind is peaceful,\npeaceful are their speech and deeds.\nSuch a one is at peace,\nrightly freed through enlightenment."
 },
 {
  "num": 97,
  "pali": "Assaddho akataññū ca,\nsandhicchedo ca yo naro;\nHatāvakāso vantāso,\nsa ve uttamaporiso.",
  "english": "Lacking faith, a house-breaker,\none who acknowledges nothing,\npurged of hope, they’ve wasted their chance:\nthat is indeed the supreme person!"
 },
 {
  "num": 98,
  "pali": "Gāme vā yadi vāraññe,\nNinne vā yadi vā thale;\nYattha arahanto viharanti,\nTaṁ bhūmirāmaṇeyyakaṁ.",
  "english": "Whether in village or wilderness,\nin a valley or the uplands,\nwherever the perfected ones live\nis a delightful place."
 },
 {
  "num": 99,
  "pali": "Ramaṇīyāni araññāni,\nyattha na ramatī jano;\nVītarāgā ramissanti,\nna te kāmagavesino.",
  "english": "Delightful are the wildernesses\nwhere no people delight.\nThose free of greed will delight there,\nnot those who seek sensual pleasures."
 },
 {
  "num": 100,
  "pali": "Sahassamapi ce vācā,\nanatthapadasaṁhitā;\nEkaṁ atthapadaṁ seyyo,\nyaṁ sutvā upasammati.",
  "english": "Better than a thousand\nmeaningless sayings\nis a single meaningful saying,\nhearing which brings you peace."
 },
 {
  "num": 101,
  "pali": "Sahassamapi ce gāthā,\nanatthapadasaṁhitā;\nEkaṁ gāthāpadaṁ seyyo,\nyaṁ sutvā upasammati.",
  "english": "Better than a thousand\nmeaningless verses\nis a single meaningful verse,\nhearing which brings you peace."
 },
 {
  "num": 102,
  "pali": "Yo ca gāthā sataṁ bhāse,\nanatthapadasaṁhitā;\nEkaṁ dhammapadaṁ seyyo,\nyaṁ sutvā upasammati.",
  "english": "Better than reciting\na hundred meaningless verses\nis a single saying of Dhamma,\nhearing which brings you peace."
 },
 {
  "num": 103,
  "pali": "Yo sahassaṁ sahassena,\nsaṅgāme mānuse jine;\nEkañca jeyyamattānaṁ,\nsa ve saṅgāmajuttamo.",
  "english": "The supreme conqueror is\nnot he who conquers a million men in battle,\nbut he who conquers a single man:\nhimself."
 },
 {
  "num": 104,
  "pali": "Attā have jitaṁ seyyo,\nyā cāyaṁ itarā pajā;\nAttadantassa posassa,\nniccaṁ saññatacārino.",
  "english": "It is surely better to conquer oneself\nthan all those other folk.\nWhen a person has tamed themselves,\nalways living restrained,"
 },
 {
  "num": 105,
  "pali": "Neva devo na gandhabbo,\nna māro saha brahmunā;\nJitaṁ apajitaṁ kayirā,\ntathārūpassa jantuno.",
  "english": "no god nor centaur,\nnor Māra nor divinity,\ncan undo the victory\nof such a personage."
 },
 {
  "num": 106,
  "pali": "Māse māse sahassena,\nyo yajetha sataṁ samaṁ;\nEkañca bhāvitattānaṁ,\nmuhuttamapi pūjaye;\nSāyeva pūjanā seyyo,\nyañce vassasataṁ hutaṁ.",
  "english": "Rather than a thousandfold sacrifice,\nevery month for a full century,\nit’s better to honor for a single hour\none who has developed themselves.\nThat offering is better\nthan the hundred year sacrifice."
 },
 {
  "num": 107,
  "pali": "Yo ca vassasataṁ jantu,\naggiṁ paricare vane;\nEkañca bhāvitattānaṁ,\nmuhuttamapi pūjaye;\nSāyeva pūjanā seyyo,\nyañce vassasataṁ hutaṁ.",
  "english": "Rather than serve the sacred flame\nin the forest for a hundred years,\nit’s better to honor for a single hour\na personage who has developed themselves.\nThat offering is better\nthan the hundred year sacrifice."
 },
 {
  "num": 108,
  "pali": "Yaṁ kiñci yiṭṭhaṁ va hutaṁ va loke,\nSaṁvaccharaṁ yajetha puññapekkho;\nSabbampi taṁ na catubhāgameti,\nAbhivādanā ujjugatesu seyyo.",
  "english": "Whatever sacrifice or offering in the world\na seeker of merit may make for a year,\nnone of it is worth a quarter\nof bowing to the sincere."
 },
 {
  "num": 109,
  "pali": "Abhivādanasīlissa,\nniccaṁ vuḍḍhāpacāyino;\nCattāro dhammā vaḍḍhanti,\nāyu vaṇṇo sukhaṁ balaṁ.",
  "english": "For one in the habit of bowing,\nalways honoring the elders,\nfour blessings grow:\nlifespan, beauty, happiness, and strength."
 },
 {
  "num": 110,
  "pali": "Yo ca vassasataṁ jīve,\ndussīlo asamāhito;\nEkāhaṁ jīvitaṁ seyyo,\nsīlavantassa jhāyino.",
  "english": "Better to live a single day\nethical and absorbed in meditation\nthan to live a hundred years\nunethical and lacking immersion."
 },
 {
  "num": 111,
  "pali": "Yo ca vassasataṁ jīve,\nduppañño asamāhito;\nEkāhaṁ jīvitaṁ seyyo,\npaññavantassa jhāyino.",
  "english": "Better to live a single day\nwise and absorbed in meditation\nthan to live a hundred years\nwitless and lacking immersion."
 },
 {
  "num": 112,
  "pali": "Yo ca vassasataṁ jīve,\nkusīto hīnavīriyo;\nEkāhaṁ jīvitaṁ seyyo,\nvīriyamārabhato daḷhaṁ.",
  "english": "Better to live a single day\nenergetic and strong,\nthan to live a hundred years\nlazy and lacking energy."
 },
 {
  "num": 113,
  "pali": "Yo ca vassasataṁ jīve,\napassaṁ udayabbayaṁ;\nEkāhaṁ jīvitaṁ seyyo,\npassato udayabbayaṁ.",
  "english": "Better to live a single day\nseeing rise and fall\nthan to live a hundred years\nblind to rise and fall."
 },
 {
  "num": 114,
  "pali": "Yo ca vassasataṁ jīve,\napassaṁ amataṁ padaṁ;\nEkāhaṁ jīvitaṁ seyyo,\npassato amataṁ padaṁ.",
  "english": "Better to live a single day\nseeing the state free of death\nthan to live a hundred years\nblind to the state free of death."
 },
 {
  "num": 115,
  "pali": "Yo ca vassasataṁ jīve,\napassaṁ dhammamuttamaṁ;\nEkāhaṁ jīvitaṁ seyyo,\npassato dhammamuttamaṁ.",
  "english": "Better to live a single day\nseeing the supreme teaching\nthan to live a hundred years\nblind to the supreme teaching."
 },
 {
  "num": 116,
  "pali": "Abhittharetha kalyāṇe,\npāpā cittaṁ nivāraye;\nDandhañhi karoto puññaṁ,\npāpasmiṁ ramatī mano.",
  "english": "Rush to do good,\nshield your mind from evil;\nfor when you’re slow to do good,\nyour thoughts delight in wickedness."
 },
 {
  "num": 117,
  "pali": "Pāpañce puriso kayirā,\nNa naṁ kayirā punappunaṁ;\nNa tamhi chandaṁ kayirātha,\nDukkho pāpassa uccayo.",
  "english": "If you do something bad,\ndon’t do it again and again,\ndon’t set your heart on it,\nfor piling up evil is suffering."
 },
 {
  "num": 118,
  "pali": "Puññañce puriso kayirā,\nkayirā naṁ punappunaṁ;\nTamhi chandaṁ kayirātha,\nsukho puññassa uccayo.",
  "english": "If you do something good,\ndo it again and again,\nset your heart on it,\nfor piling up goodness is joyful."
 },
 {
  "num": 119,
  "pali": "Pāpopi passati bhadraṁ,\nYāva pāpaṁ na paccati;\nYadā ca paccati pāpaṁ,\nAtha pāpo pāpāni passati.",
  "english": "Even the wicked see good things,\nso long as their wickedness has not ripened.\nBut as soon as that wickedness ripens,\nthen the wicked see wicked things."
 },
 {
  "num": 120,
  "pali": "Bhadropi passati pāpaṁ,\nYāva bhadraṁ na paccati;\nYadā ca paccati bhadraṁ,\nAtha bhadro bhadrāni passati.",
  "english": "Even the good see wicked things,\nso long as their goodness has not ripened.\nBut as soon as that goodness ripens,\nthen the good see good things."
 },
 {
  "num": 121,
  "pali": "Māvamaññetha pāpassa,\nna mantaṁ āgamissati;\nUdabindunipātena,\nudakumbhopi pūrati;\nBālo pūrati pāpassa,\nthokaṁ thokampi ācinaṁ.",
  "english": "Think not lightly of evil,\nthat it won’t come back to you.\nThe pot is filled with water\nfalling drop by drop;\nthe fool is filled with wickedness\npiled up bit by bit."
 },
 {
  "num": 122,
  "pali": "Māvamaññetha puññassa,\nna mandaṁ āgamissati;\nUdabindunipātena,\nudakumbhopi pūrati;\nDhīro pūrati puññassa,\nthokaṁ thokampi ācinaṁ.",
  "english": "Think not lightly of goodness,\nthat it won’t come back to you.\nThe pot is filled with water\nfalling drop by drop;\nthe attentive one is filled with goodness\npiled up bit by bit."
 },
 {
  "num": 123,
  "pali": "Vāṇijova bhayaṁ maggaṁ,\nappasattho mahaddhano;\nVisaṁ jīvitukāmova,\npāpāni parivajjaye.",
  "english": "Avoid wickedness,\nas a merchant with rich cargo and small escort\nwould avoid a dangerous road,\nor one who loves life would avoid drinking poison."
 },
 {
  "num": 124,
  "pali": "Pāṇimhi ce vaṇo nāssa,\nhareyya pāṇinā visaṁ;\nNābbaṇaṁ visamanveti,\nnatthi pāpaṁ akubbato.",
  "english": "You can carry poison in your hand\nif it has no wound,\nfor poison does not infect without a wound;\nnothing bad happens unless you do bad."
 },
 {
  "num": 125,
  "pali": "Yo appaduṭṭhassa narassa dussati,\nSuddhassa posassa anaṅgaṇassa;\nTameva bālaṁ pacceti pāpaṁ,\nSukhumo rajo paṭivātaṁva khitto.",
  "english": "Whoever wrongs a man who has done no wrong,\na pure man who has not a blemish,\nthe evil backfires on the fool,\nlike fine dust thrown upwind."
 },
 {
  "num": 126,
  "pali": "Gabbhameke uppajjanti,\nnirayaṁ pāpakammino;\nSaggaṁ sugatino yanti,\nparinibbanti anāsavā.",
  "english": "Some are born in a womb;\nevildoers go to hell;\nthe virtuous go to heaven;\nthe undefiled are fully extinguished."
 },
 {
  "num": 127,
  "pali": "Na antalikkhe na samuddamajjhe,\nNa pabbatānaṁ vivaraṁ pavissa;\nNa vijjatī so jagatippadeso,\nYatthaṭṭhito mucceyya pāpakammā.",
  "english": "Not in midair, nor mid-ocean,\nnor hiding in a mountain cleft;\nyou’ll find no place on the planet\nto escape your wicked deeds."
 },
 {
  "num": 128,
  "pali": "Na antalikkhe na samuddamajjhe,\nNa pabbatānaṁ vivaraṁ pavissa;\nNa vijjatī so jagatippadeso,\nYatthaṭṭhitaṁ nappasaheyya maccu.",
  "english": "Not in midair, nor mid-ocean,\nnor hiding in a mountain cleft;\nyou’ll find no place on the planet\nwhere you won’t be vanquished by death."
 },
 {
  "num": 129,
  "pali": "Sabbe tasanti daṇḍassa,\nsabbe bhāyanti maccuno;\nAttānaṁ upamaṁ katvā,\nna haneyya na ghātaye.",
  "english": "All tremble at the rod,\nall fear death.\nTreating others like oneself,\nneither kill nor incite to kill."
 },
 {
  "num": 130,
  "pali": "Sabbe tasanti daṇḍassa,\nsabbesaṁ jīvitaṁ piyaṁ;\nAttānaṁ upamaṁ katvā,\nna haneyya na ghātaye.",
  "english": "All tremble at the rod,\nall love life.\nTreating others like oneself,\nneither kill nor incite to kill."
 },
 {
  "num": 131,
  "pali": "Sukhakāmāni bhūtāni,\nyo daṇḍena vihiṁsati;\nAttano sukhamesāno,\npecca so na labhate sukhaṁ.",
  "english": "Creatures love happiness,\nso if you harm them with a stick\nin search of your own happiness,\nafter death you won’t find happiness."
 },
 {
  "num": 132,
  "pali": "Sukhakāmāni bhūtāni,\nyo daṇḍena na hiṁsati;\nAttano sukhamesāno,\npecca so labhate sukhaṁ.",
  "english": "Creatures love happiness,\nso if you don’t harm them with a stick\nin search of your own happiness,\nafter death you will find happiness."
 },
 {
  "num": 133,
  "pali": "Māvoca pharusaṁ kañci,\nvuttā paṭivadeyyu taṁ;\nDukkhā hi sārambhakathā,\npaṭidaṇḍā phuseyyu taṁ.",
  "english": "Don’t speak harshly,\nthey may speak harshly back.\nFor aggressive speech is painful,\nand the rod may spring back on you."
 },
 {
  "num": 134,
  "pali": "Sace neresi attānaṁ,\nkaṁso upahato yathā;\nEsa pattosi nibbānaṁ,\nsārambho te na vijjati.",
  "english": "If you still yourself\nlike a broken gong,\nyou reach extinguishment\nand know no conflict."
 },
 {
  "num": 135,
  "pali": "Yathā daṇḍena gopālo,\ngāvo pājeti gocaraṁ;\nEvaṁ jarā ca maccu ca,\nāyuṁ pājenti pāṇinaṁ.",
  "english": "As a cowherd drives the cows\nto pasture with the rod,\nso too old age and death\ndrive life from living beings."
 },
 {
  "num": 136,
  "pali": "Atha pāpāni kammāni,\nkaraṁ bālo na bujjhati;\nSehi kammehi dummedho,\naggidaḍḍhova tappati.",
  "english": "The fool does not understand\nthe evil that they do.\nBut because of those deeds, that simpleton\nis tormented as if burnt by fire."
 },
 {
  "num": 137,
  "pali": "Yo daṇḍena adaṇḍesu,\nappaduṭṭhesu dussati;\nDasannamaññataraṁ ṭhānaṁ,\nkhippameva nigacchati.",
  "english": "One who violently attacks\nthe peaceful and the innocent\nswiftly falls\nto one of ten bad states:"
 },
 {
  "num": 138,
  "pali": "Vedanaṁ pharusaṁ jāniṁ,\nsarīrassa va bhedanaṁ;\nGarukaṁ vāpi ābādhaṁ,\ncittakkhepaṁ va pāpuṇe.",
  "english": "harsh pain; loss;\nthe breakup of the body;\nserious illness;\nmental distress;"
 },
 {
  "num": 139,
  "pali": "Rājato vā upasaggaṁ,\nAbbhakkhānaṁ va dāruṇaṁ;\nParikkhayaṁ va ñātīnaṁ,\nBhogānaṁ va pabhaṅguraṁ.",
  "english": "hazards from rulers;\nvicious slander;\nloss of kin;\ndestruction of wealth;"
 },
 {
  "num": 140,
  "pali": "Atha vāssa agārāni,\naggi ḍahati pāvako;\nKāyassa bhedā duppañño,\nnirayaṁ sopapajjati.",
  "english": "or else their home\nis consumed by fire.\nWhen their body breaks up, that witless person\nis reborn in hell."
 },
 {
  "num": 141,
  "pali": "Na naggacariyā na jaṭā na paṅkā,\nNānāsakā thaṇḍilasāyikā vā;\nRajojallaṁ ukkuṭikappadhānaṁ,\nSodhenti maccaṁ avitiṇṇakaṅkhaṁ.",
  "english": "Not nudity, nor matted hair, nor mud,\nnor fasting, nor lying on bare ground,\nnor wearing dust and dirt, or squatting on the heels,\nwill cleanse a mortal not free of doubt."
 },
 {
  "num": 142,
  "pali": "Alaṅkato cepi samaṁ careyya,\nSanto danto niyato brahmacārī;\nSabbesu bhūtesu nidhāya daṇḍaṁ,\nSo brāhmaṇo so samaṇo sa bhikkhu.",
  "english": "Dressed up they may be, but if they live well—\npeaceful, tamed, committed to the spiritual path,\nhaving laid aside violence toward all creatures—\nthey are a brahmin, an ascetic, a mendicant."
 },
 {
  "num": 143,
  "pali": "Hirīnisedho puriso,\nkoci lokasmi vijjati;\nYo niddaṁ apabodheti,\nasso bhadro kasāmiva.",
  "english": "Can a person constrained by conscience\nbe found in the world?\nWho shies away from blame,\nlike a fine horse from the whip?"
 },
 {
  "num": 144,
  "pali": "Asso yathā bhadro kasāniviṭṭho,\nĀtāpino saṁvegino bhavātha;\nSaddhāya sīlena ca vīriyena ca,\nSamādhinā dhammavinicchayena ca;\nSampannavijjācaraṇā patissatā,\nJahissatha dukkhamidaṁ anappakaṁ.",
  "english": "Like a fine horse under the whip,\nbe keen and full of urgency.\nWith faith, ethics, and energy,\nimmersion, and investigation of principles,\naccomplished in knowledge and conduct, mindful,\ngive up this vast suffering."
 },
 {
  "num": 145,
  "pali": "Udakañhi nayanti nettikā,\nUsukārā namayanti tejanaṁ;\nDāruṁ namayanti tacchakā,\nAttānaṁ damayanti subbatā.",
  "english": "While irrigators guide water,\nfletchers bend arrows straight,\nand carpenters bend timber straight,\nthose true to their vows tame themselves."
 },
 {
  "num": 146,
  "pali": "Ko nu hāso kimānando,\nniccaṁ pajjalite sati;\nAndhakārena onaddhā,\npadīpaṁ na gavesatha.",
  "english": "What is joy, what is laughter,\nwhen the flames are ever burning?\nSwathed in darkness,\nwould you not seek a light?"
 },
 {
  "num": 147,
  "pali": "Passa cittakataṁ bimbaṁ,\narukāyaṁ samussitaṁ;\nĀturaṁ bahusaṅkappaṁ,\nyassa natthi dhuvaṁ ṭhiti.",
  "english": "See this fancy puppet,\na body built of sores,\ndiseased, obsessed over,\nin which nothing lasts at all."
 },
 {
  "num": 148,
  "pali": "Parijiṇṇamidaṁ rūpaṁ,\nroganīḷaṁ pabhaṅguraṁ;\nBhijjati pūtisandeho,\nmaraṇantañhi jīvitaṁ.",
  "english": "This body is decrepit and frail,\na nest of disease.\nThis foul carcass falls apart,\nfor life ends in death."
 },
 {
  "num": 149,
  "pali": "Yānimāni apatthāni,\nalābūneva sārade;\nKāpotakāni aṭṭhīni,\ntāni disvāna kā rati.",
  "english": "These dove-grey bones\nare tossed away like\ndried gourds in the autumn—\nwhat joy is there in such a sight?"
 },
 {
  "num": 150,
  "pali": "Aṭṭhīnaṁ nagaraṁ kataṁ,\nmaṁsalohitalepanaṁ;\nYattha jarā ca maccu ca,\nmāno makkho ca ohito.",
  "english": "In this city built of bones,\nplastered with flesh and blood,\nold age and death are stashed away,\nalong with conceit and contempt."
 },
 {
  "num": 151,
  "pali": "Jīranti ve rājarathā sucittā,\nAtho sarīrampi jaraṁ upeti;\nSatañca dhammo na jaraṁ upeti,\nSanto have sabbhi pavedayanti.",
  "english": "Fancy chariots of kings wear out,\nand even this body gets old.\nBut the truth of the good never gets old—\nso the good proclaim to the good."
 },
 {
  "num": 152,
  "pali": "Appassutāyaṁ puriso,\nbalībaddhova jīrati;\nMaṁsāni tassa vaḍḍhanti,\npaññā tassa na vaḍḍhati.",
  "english": "A person of little learning\nages like an ox—\ntheir flesh grows,\nbut not their wisdom."
 },
 {
  "num": 153,
  "pali": "Anekajātisaṁsāraṁ,\nsandhāvissaṁ anibbisaṁ;\nGahakāraṁ gavesanto,\ndukkhā jāti punappunaṁ.",
  "english": "Transmigrating through countless rebirths,\nI’ve journeyed without reward,\nsearching for the house-builder;\npainful is birth again and again."
 },
 {
  "num": 154,
  "pali": "Gahakāraka diṭṭhosi,\npuna gehaṁ na kāhasi;\nSabbā te phāsukā bhaggā,\ngahakūṭaṁ visaṅkhataṁ;\nVisaṅkhāragataṁ cittaṁ,\ntaṇhānaṁ khayamajjhagā.",
  "english": "I’ve seen you, house-builder!\nYou won’t build a house again!\nYour rafters are all broken,\nyour roof-peak demolished.\nThe mind, set on demolition,\nhas reached the end of cravings."
 },
 {
  "num": 155,
  "pali": "Acaritvā brahmacariyaṁ,\naladdhā yobbane dhanaṁ;\nJiṇṇakoñcāva jhāyanti,\nkhīṇamaccheva pallale.",
  "english": "When young they spurned the spiritual path\nand failed to earn any wealth.\nNow they brood like old cranes\nin a pond bereft of fish."
 },
 {
  "num": 156,
  "pali": "Acaritvā brahmacariyaṁ,\naladdhā yobbane dhanaṁ;\nSenti cāpātikhīṇāva,\npurāṇāni anutthunaṁ.",
  "english": "When young they spurned the spiritual path\nand failed to earn any wealth.\nNow they lie like spent arrows,\nbemoaning over things past."
 },
 {
  "num": 157,
  "pali": "Attānañce piyaṁ jaññā,\nrakkheyya naṁ surakkhitaṁ;\nTiṇṇaṁ aññataraṁ yāmaṁ,\npaṭijaggeyya paṇḍito.",
  "english": "If you knew your self as beloved,\nyou’d look after it so well.\nIn one of the night’s three watches,\nan astute person would remain alert."
 },
 {
  "num": 158,
  "pali": "Attānameva paṭhamaṁ,\npatirūpe nivesaye;\nAthaññamanusāseyya,\nna kilisseyya paṇḍito.",
  "english": "The astute would avoid being corrupted\nby first grounding themselves\nin what is suitable,\nand then instructing others."
 },
 {
  "num": 159,
  "pali": "Attānañce tathā kayirā,\nyathāññamanusāsati;\nSudanto vata dametha,\nattā hi kira duddamo.",
  "english": "If one were to treat oneself\nas one instructs another,\nthe well-tamed indeed would tame:\nfor the self, it seems, is hard to tame."
 },
 {
  "num": 160,
  "pali": "Attā hi attano nātho,\nko hi nātho paro siyā;\nAttanā hi sudantena,\nnāthaṁ labhati dullabhaṁ.",
  "english": "One is indeed the lord of oneself,\nfor who else would be one’s lord?\nBy means of a well-tamed self,\none gains a lord that’s rare indeed."
 },
 {
  "num": 161,
  "pali": "Attanā hi kataṁ pāpaṁ,\nAttajaṁ attasambhavaṁ;\nAbhimatthati dummedhaṁ,\nVajiraṁvasmamayaṁ maṇiṁ.",
  "english": "For the evil that is done by oneself,\nborn and produced in oneself,\ngrinds down a simpleton,\nas diamond grinds a lesser gem."
 },
 {
  "num": 162,
  "pali": "Yassa accantadussilyaṁ,\nmāluvā sālamivotthataṁ;\nKaroti so tathattānaṁ,\nyathā naṁ icchatī diso.",
  "english": "One choked by immorality,\nas a sal tree by a creeper,\ndoes to themselves\nwhat a foe only wishes."
 },
 {
  "num": 163,
  "pali": "Sukarāni asādhūni,\nattano ahitāni ca;\nYaṁ ve hitañca sādhuñca,\ntaṁ ve paramadukkaraṁ.",
  "english": "It’s easy to do bad things\nharmful to oneself,\nbut good things that are helpful\nare the hardest things to do."
 },
 {
  "num": 164,
  "pali": "Yo sāsanaṁ arahataṁ,\nariyānaṁ dhammajīvinaṁ;\nPaṭikkosati dummedho,\ndiṭṭhiṁ nissāya pāpikaṁ;\nPhalāni kaṭṭhakasseva,\nattaghātāya phallati.",
  "english": "On account of wicked views—\nscorning the guidance\nof the perfected ones,\nthe noble ones living righteously—\nthe idiot begets their own self’s demise,\nlike the bamboo bearing fruit."
 },
 {
  "num": 165,
  "pali": "Attanā hi kataṁ pāpaṁ,\nattanā saṅkilissati;\nAttanā akataṁ pāpaṁ,\nattanāva visujjhati;\nSuddhī asuddhi paccattaṁ,\nnāñño aññaṁ visodhaye.",
  "english": "For it is by oneself that evil’s done,\none is corrupted by oneself.\nIt’s by oneself that evil’s not done,\none is purified by oneself.\nPurity and impurity are personal matters,\nno one can purify another."
 },
 {
  "num": 166,
  "pali": "Attadatthaṁ paratthena,\nbahunāpi na hāpaye;\nAttadatthamabhiññāya,\nsadatthapasuto siyā.",
  "english": "Never neglect what is good for yourself\nfor the sake of another, however great.\nKnowing well what is good for yourself,\nbe intent upon your heart’s goal."
 },
 {
  "num": 167,
  "pali": "Hīnaṁ dhammaṁ na seveyya,\npamādena na saṁvase;\nMicchādiṭṭhiṁ na seveyya,\nna siyā lokavaḍḍhano.",
  "english": "Don’t resort to lowly things,\ndon’t abide in negligence,\ndon’t resort to wrong views,\ndon’t perpetuate the world."
 },
 {
  "num": 168,
  "pali": "Uttiṭṭhe nappamajjeyya,\ndhammaṁ sucaritaṁ care;\nDhammacārī sukhaṁ seti,\nasmiṁ loke paramhi ca.",
  "english": "Get up, don’t be heedless,\nlive by principle, with good conduct.\nFor one of good conduct sleeps at ease,\nin this world and the next."
 },
 {
  "num": 169,
  "pali": "Dhammaṁ care sucaritaṁ,\nna naṁ duccaritaṁ care;\nDhammacārī sukhaṁ seti,\nasmiṁ loke paramhi ca.",
  "english": "Live by principle, with good conduct,\ndon’t conduct yourself badly.\nFor one of good conduct sleeps at ease,\nin this world and the next."
 },
 {
  "num": 170,
  "pali": "Yathā pubbuḷakaṁ passe,\nyathā passe marīcikaṁ;\nEvaṁ lokaṁ avekkhantaṁ,\nmaccurājā na passati.",
  "english": "Look upon the world\nas a bubble\nor a mirage,\nthen the King of Death won’t see you."
 },
 {
  "num": 171,
  "pali": "Etha passathimaṁ lokaṁ,\ncittaṁ rājarathūpamaṁ;\nYattha bālā visīdanti,\nnatthi saṅgo vijānataṁ.",
  "english": "Come, see this world decked out\nlike a fancy royal chariot.\nHere fools founder,\nbut the discerning are not chained."
 },
 {
  "num": 172,
  "pali": "Yo ca pubbe pamajjitvā,\npacchā so nappamajjati;\nSomaṁ lokaṁ pabhāseti,\nabbhā muttova candimā.",
  "english": "He who once was heedless,\nbut turned to heedfulness,\nshines upon this world\nlike the moon freed from clouds."
 },
 {
  "num": 173,
  "pali": "Yassa pāpaṁ kataṁ kammaṁ,\nkusalena pidhīyati;\nSomaṁ lokaṁ pabhāseti,\nabbhā muttova candimā.",
  "english": "Someone whose bad deed\nis supplanted by the good,\nshines upon this world,\nlike the moon freed from clouds."
 },
 {
  "num": 174,
  "pali": "Andhabhūto ayaṁ loko,\ntanukettha vipassati;\nSakuṇo jālamuttova,\nappo saggāya gacchati.",
  "english": "Blind is the world,\nfew are those who clearly see.\nOnly a handful go to heaven,\nlike a bird freed from a net."
 },
 {
  "num": 175,
  "pali": "Haṁsādiccapathe yanti,\nākāse yanti iddhiyā;\nNīyanti dhīrā lokamhā,\njetvā māraṁ savāhiniṁ.",
  "english": "Swans fly by the sun’s path,\npsychic sages fly through space.\nThe attentive leave the world,\nhaving vanquished Māra with his legions."
 },
 {
  "num": 176,
  "pali": "Ekaṁ dhammaṁ atītassa,\nmusāvādissa jantuno;\nVitiṇṇaparalokassa,\nnatthi pāpaṁ akāriyaṁ.",
  "english": "When a personage, spurning the hereafter,\ntransgresses in just one thing—\nlying—\nthere is no evil they would not do."
 },
 {
  "num": 177,
  "pali": "Na ve kadariyā devalokaṁ vajanti,\nBālā have nappasaṁsanti dānaṁ;\nDhīro ca dānaṁ anumodamāno,\nTeneva so hoti sukhī parattha.",
  "english": "The miserly don’t ascend to heaven,\nit takes a fool to not praise giving.\nThe attentive celebrate giving,\nand so find happiness in the hereafter."
 },
 {
  "num": 178,
  "pali": "Pathabyā ekarajjena,\nsaggassa gamanena vā;\nSabbalokādhipaccena,\nsotāpattiphalaṁ varaṁ.",
  "english": "The fruit of stream-entry is better\nthan being the one king of the earth,\nthan going to heaven,\nthan lordship over all the world."
 },
 {
  "num": 179,
  "pali": "Yassa jitaṁ nāvajīyati,\nJitaṁ yassa noyāti koci loke;\nTaṁ buddhamanantagocaraṁ,\nApadaṁ kena padena nessatha.",
  "english": "He whose victory may not be undone,\na victory unrivaled in all the world;\nby what track would you trace that Buddha,\nwho leaves no track in his infinite range?"
 },
 {
  "num": 180,
  "pali": "Yassa jālinī visattikā,\nTaṇhā natthi kuhiñci netave;\nTaṁ buddhamanantagocaraṁ,\nApadaṁ kena padena nessatha.",
  "english": "Of craving, the weaver, the clinger, he has none:\nso where can he be traced?\nBy what track would you trace that Buddha,\nwho leaves no track in his infinite range?"
 },
 {
  "num": 181,
  "pali": "Ye jhānapasutā dhīrā,\nnekkhammūpasame ratā;\nDevāpi tesaṁ pihayanti,\nsambuddhānaṁ satīmataṁ.",
  "english": "The attentive intent on absorption,\nwho love the peace of renunciation,\nthe Buddhas, ever mindful,\nare envied by even the gods."
 },
 {
  "num": 182,
  "pali": "Kiccho manussapaṭilābho,\nkicchaṁ maccāna jīvitaṁ;\nKicchaṁ saddhammassavanaṁ,\nkiccho buddhānamuppādo.",
  "english": "It’s hard to gain a human birth;\nthe life of mortals is hard;\nit’s hard to hear the true teaching;\nthe arising of Buddhas is hard."
 },
 {
  "num": 183,
  "pali": "Sabbapāpassa akaraṇaṁ,\nkusalassa upasampadā;\nSacittapariyodapanaṁ,\netaṁ buddhāna sāsanaṁ.",
  "english": "Not to do any evil;\nto embrace the good;\nto purify one’s mind:\nthis is the instruction of the Buddhas."
 },
 {
  "num": 184,
  "pali": "Khantī paramaṁ tapo titikkhā,\nNibbānaṁ paramaṁ vadanti buddhā;\nNa hi pabbajito parūpaghātī,\nNa samaṇo hoti paraṁ viheṭhayanto.",
  "english": "Patient acceptance is the ultimate fervor.\nExtinguishment is the ultimate, say the Buddhas.\nNo true renunciate injures another,\nnor does an ascetic hurt another."
 },
 {
  "num": 185,
  "pali": "Anūpavādo anūpaghāto,\nPātimokkhe ca saṁvaro;\nMattaññutā ca bhattasmiṁ,\nPantañca sayanāsanaṁ;\nAdhicitte ca āyogo,\nEtaṁ buddhāna sāsanaṁ.",
  "english": "Not speaking ill nor doing harm;\nrestraint in the monastic code;\nmoderation in eating;\nstaying in remote lodgings;\ncommitment to the higher mind—\nthis is the instruction of the Buddhas."
 },
 {
  "num": 186,
  "pali": "Na kahāpaṇavassena,\ntitti kāmesu vijjati;\nAppassādā dukhā kāmā,\niti viññāya paṇḍito.",
  "english": "Even if it were raining money,\nyou’d not be sated in sensual pleasures.\nAn astute person understands that sensual pleasures\noffer little gratification and much suffering."
 },
 {
  "num": 187,
  "pali": "Api dibbesu kāmesu,\nratiṁ so nādhigacchati;\nTaṇhakkhayarato hoti,\nsammāsambuddhasāvako.",
  "english": "Thus they find no delight\neven in celestial pleasures.\nA disciple of the fully awakened Buddha\ndelights in the ending of craving."
 },
 {
  "num": 188,
  "pali": "Bahuṁ ve saraṇaṁ yanti,\npabbatāni vanāni ca;\nĀrāmarukkhacetyāni,\nmanussā bhayatajjitā.",
  "english": "So many go for refuge\nto mountains and forest groves,\nto shrines in tended parks;\nthose people are driven by fear."
 },
 {
  "num": 189,
  "pali": "Netaṁ kho saraṇaṁ khemaṁ,\nnetaṁ saraṇamuttamaṁ;\nNetaṁ saraṇamāgamma,\nsabbadukkhā pamuccati.",
  "english": "But such refuge is no sanctuary,\nit is no supreme refuge.\nBy going to that refuge,\nyou’re not released from all suffering."
 },
 {
  "num": 190,
  "pali": "Yo ca buddhañca dhammañca,\nsaṅghañca saraṇaṁ gato;\nCattāri ariyasaccāni,\nsammappaññāya passati.",
  "english": "One gone for refuge to the Buddha,\nto his teaching and to the Saṅgha,\nsees the four noble truths\nwith right understanding:"
 },
 {
  "num": 191,
  "pali": "Dukkhaṁ dukkhasamuppādaṁ,\ndukkhassa ca atikkamaṁ;\nAriyaṁ caṭṭhaṅgikaṁ maggaṁ,\ndukkhūpasamagāminaṁ.",
  "english": "suffering, suffering’s origin,\nsuffering’s transcendence,\nand the noble eightfold path\nthat leads to the stilling of suffering."
 },
 {
  "num": 192,
  "pali": "Etaṁ kho saraṇaṁ khemaṁ,\netaṁ saraṇamuttamaṁ;\nEtaṁ saraṇamāgamma,\nsabbadukkhā pamuccati.",
  "english": "Such refuge is a sanctuary,\nit is the supreme refuge.\nBy going to that refuge,\nyou’re released from all suffering."
 },
 {
  "num": 193,
  "pali": "Dullabho purisājañño,\nna so sabbattha jāyati;\nYattha so jāyati dhīro,\ntaṁ kulaṁ sukhamedhati.",
  "english": "It’s hard to find a thoroughbred man:\nthey’re not born just anywhere.\nA family where that attentive one is born\nprospers in happiness."
 },
 {
  "num": 194,
  "pali": "Sukho buddhānamuppādo,\nsukhā saddhammadesanā;\nSukhā saṅghassa sāmaggī,\nsamaggānaṁ tapo sukho.",
  "english": "Happy, the arising of Buddhas!\nHappy, the teaching of Dhamma!\nHappy is the harmony of the Saṅgha,\nand the striving of the harmonious is happy."
 },
 {
  "num": 195,
  "pali": "Pūjārahe pūjayato,\nbuddhe yadi va sāvake;\nPapañcasamatikkante,\ntiṇṇasokapariddave.",
  "english": "When a person venerates the worthy—\nthe Buddha or his disciple,\nwho have transcended proliferation,\nand have left behind grief and lamentation,"
 },
 {
  "num": 196,
  "pali": "Te tādise pūjayato,\nnibbute akutobhaye;\nNa sakkā puññaṁ saṅkhātuṁ,\nimettamapi kenaci.",
  "english": "quenched, fearing nothing from any quarter—\nthe merit of one venerating such as these,\ncannot be calculated by anyone,\nsaying it is just this much."
 },
 {
  "num": 197,
  "pali": "Susukhaṁ vata jīvāma,\nverinesu averino;\nVerinesu manussesu,\nviharāma averino.",
  "english": "Let us live so very happily,\nloving among the hostile.\nAmong hostile humans,\nlet us live with love."
 },
 {
  "num": 198,
  "pali": "Susukhaṁ vata jīvāma,\nāturesu anāturā;\nĀturesu manussesu,\nviharāma anāturā.",
  "english": "Let us live so very happily,\nhealthy among the ailing.\nAmong ailing humans\nlet us live healthily."
 },
 {
  "num": 199,
  "pali": "Susukhaṁ vata jīvāma,\nussukesu anussukā;\nUssukesu manussesu,\nviharāma anussukā.",
  "english": "Let us live so very happily,\ncontent among the greedy.\nAmong greedy humans,\nlet us live content."
 },
 {
  "num": 200,
  "pali": "Susukhaṁ vata jīvāma,\nyesaṁ no natthi kiñcanaṁ;\nPītibhakkhā bhavissāma,\ndevā ābhassarā yathā.",
  "english": "Let us live so very happily,\nwe who have nothing.\nWe shall feed on rapture,\nlike the gods of sublime luminosity."
 },
 {
  "num": 201,
  "pali": "Jayaṁ veraṁ pasavati,\ndukkhaṁ seti parājito;\nUpasanto sukhaṁ seti,\nhitvā jayaparājayaṁ.",
  "english": "Victory breeds enmity;\nthe defeated sleep badly.\nThe peaceful sleep at ease,\nhaving left victory and defeat behind."
 },
 {
  "num": 202,
  "pali": "Natthi rāgasamo aggi,\nNatthi dosasamo kali;\nNatthi khandhasamā dukkhā,\nNatthi santiparaṁ sukhaṁ.",
  "english": "There is no fire like greed,\nno crime like hate,\nno suffering like the aggregates,\nno bliss beyond peace."
 },
 {
  "num": 203,
  "pali": "Jighacchāparamā rogā,\nsaṅkhāraparamā dukhā;\nEtaṁ ñatvā yathābhūtaṁ,\nnibbānaṁ paramaṁ sukhaṁ.",
  "english": "Hunger is the worst illness,\nconditions are the worst suffering.\nWhen one has known this as it is,\nextinguishment is the ultimate happiness."
 },
 {
  "num": 204,
  "pali": "Ārogyaparamā lābhā,\nSantuṭṭhiparamaṁ dhanaṁ;\nVissāsaparamā ñāti,\nNibbānaṁ paramaṁ sukhaṁ.",
  "english": "Health is the ultimate blessing;\ncontentment, the ultimate wealth;\ntrust is the ultimate family;\nextinguishment, the ultimate happiness."
 },
 {
  "num": 205,
  "pali": "Pavivekarasaṁ pitvā,\nrasaṁ upasamassa ca;\nNiddaro hoti nippāpo,\ndhammapītirasaṁ pivaṁ.",
  "english": "Having drunk the nectar of seclusion\nand the nectar of peace—\nfree of stress, free of evil,\ndrink the joyous nectar of truth."
 },
 {
  "num": 206,
  "pali": "Sāhu dassanamariyānaṁ,\nsannivāso sadā sukho;\nAdassanena bālānaṁ,\nniccameva sukhī siyā.",
  "english": "It’s good to see the noble ones,\nstaying with them is always good.\nWere you not to see fools,\nyou’d always be happy."
 },
 {
  "num": 207,
  "pali": "Bālasaṅgatacārī hi,\ndīghamaddhāna socati;\nDukkho bālehi saṁvāso,\namitteneva sabbadā;\nDhīro ca sukhasaṁvāso,\nñātīnaṁva samāgamo.",
  "english": "For one who consorts with fools\ngrieves long.\nPainful is living with fools,\nlike being stuck with your enemy.\nHappy is living with an attentive one,\nlike meeting with your kin."
 },
 {
  "num": 208,
  "pali": "Tasmā hi—\nDhīrañca paññañca bahussutañca,\nDhorayhasīlaṁ vatavantamariyaṁ;\nTaṁ tādisaṁ sappurisaṁ sumedhaṁ,\nBhajetha nakkhattapathaṁva candimā.",
  "english": "Therefore:\nAn attentive one, wise and learned,\na behemoth of virtue, true to their vows, noble:\nfollow a true and intelligent person such as this,\nas the moon tracks the path of the stars."
 },
 {
  "num": 209,
  "pali": "Ayoge yuñjamattānaṁ,\nyogasmiñca ayojayaṁ;\nAtthaṁ hitvā piyaggāhī,\npihetattānuyoginaṁ.",
  "english": "Applying yourself where you ought not,\nneglecting what you should be doing,\nforgetting your goal, you cling to what you hold dear,\njealous of those devoted to their heart’s goal."
 },
 {
  "num": 210,
  "pali": "Mā piyehi samāgañchi,\nappiyehi kudācanaṁ;\nPiyānaṁ adassanaṁ dukkhaṁ,\nappiyānañca dassanaṁ.",
  "english": "Don’t ever get too close\nto those you like or dislike.\nFor not seeing the liked is suffering,\nand so is seeing the disliked."
 },
 {
  "num": 211,
  "pali": "Tasmā piyaṁ na kayirātha,\npiyāpāyo hi pāpako;\nGanthā tesaṁ na vijjanti,\nyesaṁ natthi piyāppiyaṁ.",
  "english": "Therefore don’t hold anything dear,\nfor it’s bad to lose those you love.\nNo ties are found in they who\nhold nothing loved or loathed."
 },
 {
  "num": 212,
  "pali": "Piyato jāyatī soko,\npiyato jāyatī bhayaṁ;\nPiyato vippamuttassa,\nnatthi soko kuto bhayaṁ.",
  "english": "Sorrow springs from what we hold dear,\nfear springs from what we hold dear;\none free from holding anything dear\nhas no sorrow, let alone fear."
 },
 {
  "num": 213,
  "pali": "Pemato jāyatī soko,\npemato jāyatī bhayaṁ;\nPemato vippamuttassa,\nnatthi soko kuto bhayaṁ.",
  "english": "Sorrow springs from attachment,\nfear springs from attachment;\none free from attachment\nhas no sorrow, let alone fear."
 },
 {
  "num": 214,
  "pali": "Ratiyā jāyatī soko,\nratiyā jāyatī bhayaṁ;\nRatiyā vippamuttassa,\nnatthi soko kuto bhayaṁ.",
  "english": "Sorrow springs from relishing,\nfear springs from relishing;\none free from relishing\nhas no sorrow, let alone fear."
 },
 {
  "num": 215,
  "pali": "Kāmato jāyatī soko,\nkāmato jāyatī bhayaṁ;\nKāmato vippamuttassa,\nnatthi soko kuto bhayaṁ.",
  "english": "Sorrow springs from desire,\nfear springs from desire;\none free from desire\nhas no sorrow, let alone fear."
 },
 {
  "num": 216,
  "pali": "Taṇhāya jāyatī soko,\ntaṇhāya jāyatī bhayaṁ;\nTaṇhāya vippamuttassa,\nnatthi soko kuto bhayaṁ.",
  "english": "Sorrow springs from craving,\nfear springs from craving;\none free from craving\nhas no sorrow, let alone fear."
 },
 {
  "num": 217,
  "pali": "Sīladassanasampannaṁ,\ndhammaṭṭhaṁ saccavedinaṁ;\nAttano kamma kubbānaṁ,\ntaṁ jano kurute piyaṁ.",
  "english": "One accomplished in virtue and vision,\nfirmly principled, and truthful,\ndoing oneself what ought be done:\nthat’s who the people love."
 },
 {
  "num": 218,
  "pali": "Chandajāto anakkhāte,\nManasā ca phuṭo siyā;\nKāmesu ca appaṭibaddhacitto,\nUddhaṁsototi vuccati.",
  "english": "One eager to realize the ineffable\nwould be filled with awareness.\nTheir mind not bound to pleasures of sense,\nthey’re said to be heading upstream."
 },
 {
  "num": 219,
  "pali": "Cirappavāsiṁ purisaṁ,\ndūrato sotthimāgataṁ;\nÑātimittā suhajjā ca,\nabhinandanti āgataṁ.",
  "english": "When a man returns safely\nafter a long time spent abroad,\nfamily, friends, and loved ones\ncelebrate his return."
 },
 {
  "num": 220,
  "pali": "Tatheva katapuññampi,\nasmā lokā paraṁ gataṁ;\nPuññāni paṭigaṇhanti,\npiyaṁ ñātīva āgataṁ.",
  "english": "Just so, when one who has done good\ngoes from this world to the next,\ntheir good deeds receive them there,\nas family welcomes home one they love."
 },
 {
  "num": 221,
  "pali": "Kodhaṁ jahe vippajaheyya mānaṁ,\nSaṁyojanaṁ sabbamatikkameyya;\nTaṁ nāmarūpasmimasajjamānaṁ,\nAkiñcanaṁ nānupatanti dukkhā.",
  "english": "Give up anger, get rid of conceit,\nand escape every fetter.\nSufferings don’t befall one who has nothing,\nnot clinging to name and form."
 },
 {
  "num": 222,
  "pali": "Yo ve uppatitaṁ kodhaṁ,\nrathaṁ bhantaṁva vāraye;\nTamahaṁ sārathiṁ brūmi,\nrasmiggāho itaro jano.",
  "english": "When anger surges like a lurching chariot,\nkeep it in check.\nThat’s what I call a charioteer;\nothers just hold the reins."
 },
 {
  "num": 223,
  "pali": "Akkodhena jine kodhaṁ,\nasādhuṁ sādhunā jine;\nJine kadariyaṁ dānena,\nsaccenālikavādinaṁ.",
  "english": "Defeat anger with kindness,\nvillainy with virtue,\nstinginess with giving,\nand lies with truth."
 },
 {
  "num": 224,
  "pali": "Saccaṁ bhaṇe na kujjheyya,\ndajjā appampi yācito;\nEtehi tīhi ṭhānehi,\ngacche devāna santike.",
  "english": "Speak the truth, do not be angry,\nand give when asked, if only a little.\nBy these three means,\nyou may enter the presence of the gods."
 },
 {
  "num": 225,
  "pali": "Ahiṁsakā ye munayo,\nniccaṁ kāyena saṁvutā;\nTe yanti accutaṁ ṭhānaṁ,\nyattha gantvā na socare.",
  "english": "Those harmless sages,\nalways restrained in body,\ngo to the state that does not pass,\nwhere there is no sorrow."
 },
 {
  "num": 226,
  "pali": "Sadā jāgaramānānaṁ,\nahorattānusikkhinaṁ;\nNibbānaṁ adhimuttānaṁ,\natthaṁ gacchanti āsavā.",
  "english": "Always wakeful,\npracticing night and day,\nfocused only on extinguishment,\ntheir defilements come to an end."
 },
 {
  "num": 227,
  "pali": "Porāṇametaṁ atula,\nnetaṁ ajjatanāmiva;\nNindanti tuṇhimāsīnaṁ,\nnindanti bahubhāṇinaṁ;\nMitabhāṇimpi nindanti,\nnatthi loke anindito.",
  "english": "It’s always been this way, Atula,\nit’s not just today.\nThey blame you when you’re silent,\nthey blame you when you speak a lot,\nand even when you speak just right:\nno one in the world escapes blame."
 },
 {
  "num": 228,
  "pali": "Na cāhu na ca bhavissati,\nna cetarahi vijjati;\nEkantaṁ nindito poso,\nekantaṁ vā pasaṁsito.",
  "english": "There never was, nor will be,\nnor is there today,\nsomeone who is wholly praised\nor wholly blamed."
 },
 {
  "num": 229,
  "pali": "Yañce viññū pasaṁsanti,\nanuvicca suve suve;\nAcchiddavuttiṁ medhāviṁ,\npaññāsīlasamāhitaṁ.",
  "english": "If, after watching them day in day out,\ndiscerning people praise\nthat sage of impeccable conduct,\nendowed with ethics and wisdom;"
 },
 {
  "num": 230,
  "pali": "Nikkhaṁ jambonadasseva,\nko taṁ ninditumarahati;\nDevāpi naṁ pasaṁsanti,\nbrahmunāpi pasaṁsito.",
  "english": "like a pendant of Black Plum River gold,\nwho is worthy to criticize them?\nEven the gods praise them,\nand by the Divinity, too, they’re praised."
 },
 {
  "num": 231,
  "pali": "Kāyappakopaṁ rakkheyya,\nkāyena saṁvuto siyā;\nKāyaduccaritaṁ hitvā,\nkāyena sucaritaṁ care.",
  "english": "Guard against ill-tempered deeds,\nbe restrained in body.\nGiving up bad bodily conduct,\nconduct yourself well in body."
 },
 {
  "num": 232,
  "pali": "Vacīpakopaṁ rakkheyya,\nvācāya saṁvuto siyā;\nVacīduccaritaṁ hitvā,\nvācāya sucaritaṁ care.",
  "english": "Guard against ill-tempered words,\nbe restrained in speech.\nGiving up bad verbal conduct,\nconduct yourself well in speech."
 },
 {
  "num": 233,
  "pali": "Manopakopaṁ rakkheyya,\nmanasā saṁvuto siyā;\nManoduccaritaṁ hitvā,\nmanasā sucaritaṁ care.",
  "english": "Guard against ill-tempered thoughts,\nbe restrained in mind.\nGiving up bad mental conduct,\nconduct yourself well in mind."
 },
 {
  "num": 234,
  "pali": "Kāyena saṁvutā dhīrā,\natho vācāya saṁvutā;\nManasā saṁvutā dhīrā,\nte ve suparisaṁvutā.",
  "english": "An attentive one is restrained in body\nrestrained also in speech,\nin thought, too, they are restrained:\nthey are restrained in every way."
 },
 {
  "num": 235,
  "pali": "Paṇḍupalāsova dānisi,\nYamapurisāpi ca te upaṭṭhitā;\nUyyogamukhe ca tiṭṭhasi,\nPātheyyampi ca te na vijjati.",
  "english": "Today you’re like a withered leaf,\nYama’s men await you.\nYou stand at the departure gates,\nyet you have no supplies for the road."
 },
 {
  "num": 236,
  "pali": "So karohi dīpamattano,\nKhippaṁ vāyama paṇḍito bhava;\nNiddhantamalo anaṅgaṇo,\nDibbaṁ ariyabhūmiṁ upehisi.",
  "english": "Make an island of yourself!\nSwiftly strive, learn to be wise!\nPurged of stains, flawless,\nyou’ll go to the heavenly realm of the noble ones."
 },
 {
  "num": 237,
  "pali": "Upanītavayo ca dānisi,\nSampayātosi yamassa santikaṁ;\nVāso te natthi antarā,\nPātheyyampi ca te na vijjati.",
  "english": "You’ve journeyed the stages of life,\nand now you set out to meet Yama.\nAlong the way there’s nowhere to stay,\nyet you have no supplies for the road."
 },
 {
  "num": 238,
  "pali": "So karohi dīpamattano,\nKhippaṁ vāyama paṇḍito bhava;\nNiddhantamalo anaṅgaṇo,\nNa punaṁ jātijaraṁ upehisi.",
  "english": "Make an island of yourself!\nSwiftly strive, learn to be wise!\nPurged of stains, flawless,\nyou’ll not come again to rebirth and old age."
 },
 {
  "num": 239,
  "pali": "Anupubbena medhāvī,\nthokaṁ thokaṁ khaṇe khaṇe;\nKammāro rajatasseva,\nniddhame malamattano.",
  "english": "A smart person would purge\ntheir own stains gradually,\nbit by bit, moment by moment,\nlike a smith smelting silver."
 },
 {
  "num": 240,
  "pali": "Ayasāva malaṁ samuṭṭhitaṁ,\nTatuṭṭhāya tameva khādati;\nEvaṁ atidhonacārinaṁ,\nSāni kammāni nayanti duggatiṁ.",
  "english": "It is the rust born on the iron\nthat eats away the place it arose.\nAnd so it is their own deeds\nthat lead the overly-ascetic to a bad place."
 },
 {
  "num": 241,
  "pali": "Asajjhāyamalā mantā,\nanuṭṭhānamalā gharā;\nMalaṁ vaṇṇassa kosajjaṁ,\npamādo rakkhato malaṁ.",
  "english": "Not rehearsing is the stain of hymns.\nThe stain of houses is neglect.\nLaziness is the stain of beauty.\nA guard’s stain is negligence."
 },
 {
  "num": 242,
  "pali": "Malitthiyā duccaritaṁ,\nmaccheraṁ dadato malaṁ;\nMalā ve pāpakā dhammā,\nasmiṁ loke paramhi ca.",
  "english": "Misconduct is a woman’s stain.\nA giver’s stain is stinginess.\nBad qualities are a stain\nin this world and the next."
 },
 {
  "num": 243,
  "pali": "Tato malā malataraṁ,\navijjā paramaṁ malaṁ;\nEtaṁ malaṁ pahantvāna,\nnimmalā hotha bhikkhavo.",
  "english": "But a worse stain than these\nis ignorance, the worst stain of all.\nHaving given up that stain,\nbe without stains, mendicants!"
 },
 {
  "num": 244,
  "pali": "Sujīvaṁ ahirikena,\nkākasūrena dhaṁsinā;\nPakkhandinā pagabbhena,\nsaṅkiliṭṭhena jīvitaṁ.",
  "english": "Life is easy for the shameless.\nWith all the rude courage of a crow,\nthey live pushy,\nrude, and corrupt."
 },
 {
  "num": 245,
  "pali": "Hirīmatā ca dujjīvaṁ,\nniccaṁ sucigavesinā;\nAlīnenāppagabbhena,\nsuddhājīvena passatā.",
  "english": "Life is hard for the conscientious,\nalways seeking purity,\nneither clinging nor rude,\npure of livelihood and discerning."
 },
 {
  "num": 246,
  "pali": "Yo pāṇamatipāteti,\nmusāvādañca bhāsati;\nLoke adinnamādiyati,\nparadārañca gacchati.",
  "english": "Take anyone in this world\nwho kills living creatures,\nspeaks falsely, steals,\ncommits adultery,"
 },
 {
  "num": 247,
  "pali": "Surāmerayapānañca,\nyo naro anuyuñjati;\nIdheva meso lokasmiṁ,\nmūlaṁ khaṇati attano.",
  "english": "and indulges in drinking\nbeer and wine.\nRight here they dig up\nthe root of their own self."
 },
 {
  "num": 248,
  "pali": "Evaṁ bho purisa jānāhi,\npāpadhammā asaññatā;\nMā taṁ lobho adhammo ca,\nciraṁ dukkhāya randhayuṁ.",
  "english": "Know this, my man:\nthey are unrestrained and wicked.\nDon’t let that greed and unrighteousness\ninflict pain on you for long."
 },
 {
  "num": 249,
  "pali": "Dadāti ve yathāsaddhaṁ,\nyathāpasādanaṁ jano;\nTattha yo ca maṅku bhavati,\nparesaṁ pānabhojane;\nNa so divā vā rattiṁ vā,\nsamādhimadhigacchati.",
  "english": "The people give according to their faith,\naccording to their confidence.\nIf you get upset over that,\nover others’ food and drink,\nyou’ll not, by day or by night,\nbecome immersed in samādhi."
 },
 {
  "num": 250,
  "pali": "Yassa cetaṁ samucchinnaṁ,\nmūlaghaccaṁ samūhataṁ;\nSa ve divā vā rattiṁ vā,\nsamādhimadhigacchati.",
  "english": "Those who have cut that out,\ndug it up at the root, eradicated it,\nthey will, by day or by night,\nbecome immersed in samādhi."
 },
 {
  "num": 251,
  "pali": "Natthi rāgasamo aggi,\nnatthi dosasamo gaho;\nNatthi mohasamaṁ jālaṁ,\nnatthi taṇhāsamā nadī.",
  "english": "There is no fire like greed,\nno crime like hate,\nno net like delusion,\nno river like craving."
 },
 {
  "num": 252,
  "pali": "Sudassaṁ vajjamaññesaṁ,\nattano pana duddasaṁ;\nParesaṁ hi so vajjāni,\nopunāti yathā bhusaṁ;\nAttano pana chādeti,\nkaliṁva kitavā saṭho.",
  "english": "It’s easy to see the faults of others,\nhard to see one’s own.\nFor the faults of others\nare tossed high like hay,\nwhile one’s own are hidden,\nas a cheat hides a bad hand."
 },
 {
  "num": 253,
  "pali": "Paravajjānupassissa,\nniccaṁ ujjhānasaññino;\nĀsavā tassa vaḍḍhanti,\nārā so āsavakkhayā.",
  "english": "When you look for the flaws of others,\nalways finding fault,\nyour defilements only grow,\nyou’re far from ending defilements."
 },
 {
  "num": 254,
  "pali": "Ākāseva padaṁ natthi,\nsamaṇo natthi bāhire;\nPapañcābhiratā pajā,\nnippapañcā tathāgatā.",
  "english": "In the atmosphere there is no track,\nthere’s no true ascetic outside here.\nPeople enjoy proliferation,\nthe Realized Ones are free of proliferation."
 },
 {
  "num": 255,
  "pali": "Ākāseva padaṁ natthi,\nsamaṇo natthi bāhire;\nSaṅkhārā sassatā natthi,\nnatthi buddhānamiñjitaṁ.",
  "english": "In the atmosphere there is no track,\nthere’s no true ascetic outside here.\nNo conditions last forever,\nthe Awakened Ones are not shaken."
 },
 {
  "num": 256,
  "pali": "Na tena hoti dhammaṭṭho,\nyenatthaṁ sāhasā naye;\nYo ca atthaṁ anatthañca,\nubho niccheyya paṇḍito.",
  "english": "You don’t become just\nby passing hasty judgment.\nAn astute person evaluates both\nwhat is pertinent and what is irrelevant."
 },
 {
  "num": 257,
  "pali": "Asāhasena dhammena,\nsamena nayatī pare;\nDhammassa gutto medhāvī,\n“dhammaṭṭho”ti pavuccati.",
  "english": "A wise one judges others without haste,\njustly and impartially;\nthat guardian of the law\nis said to be just."
 },
 {
  "num": 258,
  "pali": "Na tena paṇḍito hoti,\nyāvatā bahu bhāsati;\nKhemī averī abhayo,\n“paṇḍito”ti pavuccati.",
  "english": "You’re not an astute scholar\njust because you speak a lot.\nOne who is secure, free of enmity and fear,\nis said to be astute."
 },
 {
  "num": 259,
  "pali": "Na tāvatā dhammadharo,\nyāvatā bahu bhāsati;\nYo ca appampi sutvāna,\ndhammaṁ kāyena passati;\nSa ve dhammadharo hoti,\nyo dhammaṁ nappamajjati.",
  "english": "You’re not one who has memorized the teaching\njust because you recite a lot.\nSomeone who directly sees the teaching\nafter hearing only a little\nis truly one who has memorized the teaching,\nfor they can never forget it."
 },
 {
  "num": 260,
  "pali": "Na tena thero so hoti,\nyenassa palitaṁ siro;\nParipakko vayo tassa,\n“moghajiṇṇo”ti vuccati.",
  "english": "You don’t become a senior\nby getting some grey hairs;\nfor one ripe only in age,\nis said to have aged in vain."
 },
 {
  "num": 261,
  "pali": "Yamhi saccañca dhammo ca,\nahiṁsā saṁyamo damo;\nSa ve vantamalo dhīro,\n“thero” iti pavuccati.",
  "english": "One who is truthful and principled,\nharmless, restrained, and self-controlled,\nattentive, purged of stains,\nis said to be a senior."
 },
 {
  "num": 262,
  "pali": "Na vākkaraṇamattena,\nvaṇṇapokkharatāya vā;\nSādhurūpo naro hoti,\nissukī maccharī saṭho.",
  "english": "Not by mere enunciation,\nor a beautiful complexion\ndoes a person become holy,\nif they’re jealous, stingy, and devious."
 },
 {
  "num": 263,
  "pali": "Yassa cetaṁ samucchinnaṁ,\nmūlaghaccaṁ samūhataṁ;\nSa vantadoso medhāvī,\n“sādhurūpo”ti vuccati.",
  "english": "But if they’ve cut that out,\ndug it up at the root, eradicated it,\nthat intelligent one, purged of vice,\nis said to be holy."
 },
 {
  "num": 264,
  "pali": "Na muṇḍakena samaṇo,\nabbato alikaṁ bhaṇaṁ;\nIcchālobhasamāpanno,\nsamaṇo kiṁ bhavissati.",
  "english": "A liar and breaker of vows is no ascetic\njust because they shave their head.\nHow on earth can one be an ascetic\nwho’s full of desire and greed?"
 },
 {
  "num": 265,
  "pali": "Yo ca sameti pāpāni,\naṇuṁthūlāni sabbaso;\nSamitattā hi pāpānaṁ,\n“samaṇo”ti pavuccati.",
  "english": "One who stops all wicked deeds,\ngreat and small,\nbecause of stopping wicked deeds\nis said to be an ascetic."
 },
 {
  "num": 266,
  "pali": "Na tena bhikkhu so hoti,\nyāvatā bhikkhate pare;\nVissaṁ dhammaṁ samādāya,\nbhikkhu hoti na tāvatā.",
  "english": "You don’t become a mendicant\njust by begging from others.\nOne who has undertaken domestic duties\nhas not yet become a mendicant."
 },
 {
  "num": 267,
  "pali": "Yodha puññañca pāpañca,\nbāhetvā brahmacariyavā;\nSaṅkhāya loke carati,\nsa ve “bhikkhū”ti vuccati.",
  "english": "But one living a spiritual life,\nwho has banished both merit and evil,\nwho wanders having appraised the world,\nis said to be a mendicant."
 },
 {
  "num": 268,
  "pali": "Na monena munī hoti,\nmūḷharūpo aviddasu;\nYo ca tulaṁva paggayha,\nvaramādāya paṇḍito.",
  "english": "You don’t become a sage by being sagelike,\nwhile still confused and ignorant.\nThe astute one who holds the scales,\ntaking only the best,"
 },
 {
  "num": 269,
  "pali": "Pāpāni parivajjeti,\nsa munī tena so muni;\nYo munāti ubho loke,\n“muni” tena pavuccati.",
  "english": "and shunning the bad—\nthat is a sage, <j>and that is how one becomes a sage.\nOne who sagely weighs both in the world,\nis thereby said to be a sage."
 },
 {
  "num": 270,
  "pali": "Na tena ariyo hoti,\nyena pāṇāni hiṁsati;\nAhiṁsā sabbapāṇānaṁ,\n“ariyo”ti pavuccati.",
  "english": "You don’t become a noble one\nby harming living beings.\nOne harmless toward all living beings\nis said to be a noble one."
 },
 {
  "num": 271,
  "pali": "Na sīlabbatamattena,\nbāhusaccena vā pana;\nAtha vā samādhilābhena,\nvivittasayanena vā.",
  "english": "Not by precepts and observances,\nnor by much learning,\nnor by meditative immersion,\nnor by living in seclusion,"
 },
 {
  "num": 272,
  "pali": "Phusāmi nekkhammasukhaṁ,\naputhujjanasevitaṁ;\nBhikkhu vissāsamāpādi,\nappatto āsavakkhayaṁ.",
  "english": "do I experience the bliss of renunciation\nnot frequented by ordinary people.\nA mendicant cannot rest confident\nwithout attaining the end of defilements."
 },
 {
  "num": 273,
  "pali": "Maggānaṭṭhaṅgiko seṭṭho,\nsaccānaṁ caturo padā;\nVirāgo seṭṭho dhammānaṁ,\ndvipadānañca cakkhumā.",
  "english": "Of paths, the eightfold is the best;\nof truths, the four statements;\ndispassion is the best of things,\nand the Clear-eyed One is the best of humans."
 },
 {
  "num": 274,
  "pali": "Eseva maggo natthañño,\nDassanassa visuddhiyā;\nEtañhi tumhe paṭipajjatha,\nMārassetaṁ pamohanaṁ.",
  "english": "<em>This</em> is the path, there is no other\nfor the purification of vision.\nYou all must practice this,\nit is the way to baffle Māra."
 },
 {
  "num": 275,
  "pali": "Etañhi tumhe paṭipannā,\ndukkhassantaṁ karissatha;\nAkkhāto vo mayā maggo,\naññāya sallakantanaṁ.",
  "english": "When you all are practicing this,\nyou’ll make an end of suffering.\nI have explained the path to you\nfor extracting the thorn with wisdom."
 },
 {
  "num": 276,
  "pali": "Tumhehi kiccamātappaṁ,\nakkhātāro tathāgatā;\nPaṭipannā pamokkhanti,\njhāyino mārabandhanā.",
  "english": "You yourselves must do the work,\nthe Realized Ones just show the way.\nMeditators practicing absorption\nare released from Māra’s bonds."
 },
 {
  "num": 277,
  "pali": "“Sabbe saṅkhārā aniccā”ti,\nyadā paññāya passati;\nAtha nibbindati dukkhe,\nesa maggo visuddhiyā.",
  "english": "All conditions are impermanent—\nwhen this is seen with wisdom,\none grows disillusioned with suffering:\nthis is the path to purity."
 },
 {
  "num": 278,
  "pali": "“Sabbe saṅkhārā dukkhā”ti,\nyadā paññāya passati;\nAtha nibbindati dukkhe,\nesa maggo visuddhiyā.",
  "english": "All conditions are suffering—\nwhen this is seen with wisdom,\none grows disillusioned with suffering:\nthis is the path to purity."
 },
 {
  "num": 279,
  "pali": "“Sabbe dhammā anattā”ti,\nyadā paññāya passati;\nAtha nibbindati dukkhe,\nesa maggo visuddhiyā.",
  "english": "All things are not-self—\nwhen this is seen with wisdom,\none grows disillusioned with suffering:\nthis is the path to purity."
 },
 {
  "num": 280,
  "pali": "Uṭṭhānakālamhi anuṭṭhahāno,\nYuvā balī ālasiyaṁ upeto;\nSaṁsannasaṅkappamano kusīto,\nPaññāya maggaṁ alaso na vindati.",
  "english": "They don’t get going when it’s time to start;\nthey’re young and strong, but given to sloth.\nTheir mind depressed in sunken thought,\nlazy and slothful, they can’t discern the path."
 },
 {
  "num": 281,
  "pali": "Vācānurakkhī manasā susaṁvuto,\nKāyena ca nākusalaṁ kayirā;\nEte tayo kammapathe visodhaye,\nĀrādhaye maggamisippaveditaṁ.",
  "english": "Guarded in speech, restrained in mind,\ndoing no unskillful bodily deed.\nPurify these three ways of performing deeds,\nand win the path known to seers."
 },
 {
  "num": 282,
  "pali": "Yogā ve jāyatī bhūri,\nayogā bhūrisaṅkhayo;\nEtaṁ dvedhāpathaṁ ñatvā,\nbhavāya vibhavāya ca;\nTathāttānaṁ niveseyya,\nyathā bhūri pavaḍḍhati.",
  "english": "From meditation springs wisdom,\nwithout meditation, wisdom ends.\nKnowing these two paths—\nof progress and decline—\nyou should conduct yourself\nso that wisdom grows."
 },
 {
  "num": 283,
  "pali": "Vanaṁ chindatha mā rukkhaṁ,\nvanato jāyate bhayaṁ;\nChetvā vanañca vanathañca,\nnibbanā hotha bhikkhavo.",
  "english": "Cut down the jungle, not just a tree;\nfrom the jungle springs fear.\nHaving cut down jungle and snarl,\nbe free of jungles, mendicants!"
 },
 {
  "num": 284,
  "pali": "Yāva hi vanatho na chijjati,\nAṇumattopi narassa nārisu;\nPaṭibaddhamanova tāva so,\nVaccho khīrapakova mātari.",
  "english": "So long as the vine, no matter how small,\nthat ties a man to women is not cut,\nhis mind remains trapped,\nlike a calf suckling its mother."
 },
 {
  "num": 285,
  "pali": "Ucchinda sinehamattano,\nKumudaṁ sāradikaṁva pāṇinā;\nSantimaggameva brūhaya,\nNibbānaṁ sugatena desitaṁ.",
  "english": "Cut out affection for oneself,\nlike plucking an autumn lotus.\nFoster only the path to peace,\nthe extinguishment the Holy One taught."
 },
 {
  "num": 286,
  "pali": "Idha vassaṁ vasissāmi,\nidha hemantagimhisu;\nIti bālo vicinteti,\nantarāyaṁ na bujjhati.",
  "english": "“Here I will stay for the rains;\nhere for winter, here the summer”;\nthus the fool thinks,\nnot realizing the danger."
 },
 {
  "num": 287,
  "pali": "Taṁ puttapasusammattaṁ,\nbyāsattamanasaṁ naraṁ;\nSuttaṁ gāmaṁ mahoghova,\nmaccu ādāya gacchati.",
  "english": "As a mighty flood sweeps away a sleeping village,\ndeath steals away a man\nwho dotes on children and cattle,\nhis mind caught up in them."
 },
 {
  "num": 288,
  "pali": "Na santi puttā tāṇāya,\nna pitā nāpi bandhavā;\nAntakenādhipannassa,\nnatthi ñātīsu tāṇatā.",
  "english": "Children provide you no shelter,\nnor does father, nor relatives.\nWhen you’re seized by the terminator,\nthere’s no shelter in family."
 },
 {
  "num": 289,
  "pali": "Etamatthavasaṁ ñatvā,\npaṇḍito sīlasaṁvuto;\nNibbānagamanaṁ maggaṁ,\nkhippameva visodhaye.",
  "english": "Knowing the reason for this,\nastute, and ethically restrained,\none would quickly clear the path\nthat leads to extinguishment."
 },
 {
  "num": 290,
  "pali": "Mattāsukhapariccāgā,\npasse ce vipulaṁ sukhaṁ;\nCaje mattāsukhaṁ dhīro,\nsampassaṁ vipulaṁ sukhaṁ.",
  "english": "If by giving up material happiness\none sees abundant happiness,\nthe attentive would give up material happiness,\nseeing the abundant happiness."
 },
 {
  "num": 291,
  "pali": "Paradukkhūpadhānena,\nattano sukhamicchati;\nVerasaṁsaggasaṁsaṭṭho,\nverā so na parimuccati.",
  "english": "Seeking their own happiness\nby imposing suffering on others,\nintimate with enmity,\nthey’re not freed from enmity."
 },
 {
  "num": 292,
  "pali": "Yañhi kiccaṁ apaviddhaṁ,\nakiccaṁ pana karīyati;\nUnnaḷānaṁ pamattānaṁ,\ntesaṁ vaḍḍhanti āsavā.",
  "english": "They dump what should be done,\nand do what should not be done.\nFor the insolent and the negligent,\ntheir defilements only grow."
 },
 {
  "num": 293,
  "pali": "Yesañca susamāraddhā,\nniccaṁ kāyagatā sati;\nAkiccaṁ te na sevanti,\nkicce sātaccakārino;\nSatānaṁ sampajānānaṁ,\natthaṁ gacchanti āsavā.",
  "english": "Those that have properly undertaken\nconstant mindfulness of the body,\ndon’t cultivate what should not be done,\nbut always do what should be done.\nMindful and aware,\ntheir defilements come to an end."
 },
 {
  "num": 294,
  "pali": "Mātaraṁ pitaraṁ hantvā,\nrājāno dve ca khattiye;\nRaṭṭhaṁ sānucaraṁ hantvā,\nanīgho yāti brāhmaṇo.",
  "english": "Having slain mother and father,\nand two aristocratic kings,\nand having wiped out <j>the kingdom with its tax collector,\nthe brahmin walks on untroubled."
 },
 {
  "num": 295,
  "pali": "Mātaraṁ pitaraṁ hantvā,\nrājāno dve ca sotthiye;\nVeyagghapañcamaṁ hantvā,\nanīgho yāti brāhmaṇo.",
  "english": "Having slain mother and father,\nand two prosperous kings,\nand a tiger as the fifth,\nthe brahmin walks on untroubled."
 },
 {
  "num": 296,
  "pali": "Suppabuddhaṁ pabujjhanti,\nsadā gotamasāvakā;\nYesaṁ divā ca ratto ca,\nniccaṁ buddhagatā sati.",
  "english": "The disciples of Gotama\nalways wake up refreshed,\nwho day and night\nconstantly recollect the Buddha."
 },
 {
  "num": 297,
  "pali": "Suppabuddhaṁ pabujjhanti,\nsadā gotamasāvakā;\nYesaṁ divā ca ratto ca,\nniccaṁ dhammagatā sati.",
  "english": "The disciples of Gotama\nalways wake up refreshed,\nwho day and night\nconstantly recollect the teaching."
 },
 {
  "num": 298,
  "pali": "Suppabuddhaṁ pabujjhanti,\nsadā gotamasāvakā;\nYesaṁ divā ca ratto ca,\nniccaṁ saṅghagatā sati.",
  "english": "The disciples of Gotama\nalways wake up refreshed,\nwho day and night\nconstantly recollect the Saṅgha."
 },
 {
  "num": 299,
  "pali": "Suppabuddhaṁ pabujjhanti,\nsadā gotamasāvakā;\nYesaṁ divā ca ratto ca,\nniccaṁ kāyagatā sati.",
  "english": "The disciples of Gotama\nalways wake up refreshed,\nwho day and night\nare constantly mindful of the body."
 },
 {
  "num": 300,
  "pali": "Suppabuddhaṁ pabujjhanti,\nsadā gotamasāvakā;\nYesaṁ divā ca ratto ca,\nahiṁsāya rato mano.",
  "english": "The disciples of Gotama\nalways wake up refreshed,\nwhose minds day and night\ndelight in harmlessness."
 },
 {
  "num": 301,
  "pali": "Suppabuddhaṁ pabujjhanti,\nsadā gotamasāvakā;\nYesaṁ divā ca ratto ca,\nbhāvanāya rato mano.",
  "english": "The disciples of Gotama\nalways wake up refreshed,\nwhose minds day and night\ndelight in meditation."
 },
 {
  "num": 302,
  "pali": "Duppabbajjaṁ durabhiramaṁ,\nDurāvāsā gharā dukhā;\nDukkhosamānasaṁvāso,\nDukkhānupatitaddhagū;\nTasmā na caddhagū siyā,\nNa ca dukkhānupatito siyā.",
  "english": "Going forth is hard, it’s hard to be happy;\nlife at home is hard too, and painful,\nit’s painful to stay when you’ve nothing in common.\nA traveler is a prey to pain,\nso don’t be a traveler,\ndon’t be prey to pain."
 },
 {
  "num": 303,
  "pali": "Saddho sīlena sampanno,\nyasobhogasamappito;\nYaṁ yaṁ padesaṁ bhajati,\ntattha tattheva pūjito.",
  "english": "One who is faithful, accomplished in ethics,\nblessed with fame and wealth,\nis honored in whatever place\nthey frequent."
 },
 {
  "num": 304,
  "pali": "Dūre santo pakāsenti,\nhimavantova pabbato;\nAsantettha na dissanti,\nrattiṁ khittā yathā sarā.",
  "english": "The good shine from afar,\nlike the Himalayan peaks,\nbut the wicked are not seen,\nlike arrows scattered in the night."
 },
 {
  "num": 305,
  "pali": "Ekāsanaṁ ekaseyyaṁ,\neko caramatandito;\nEko damayamattānaṁ,\nvanante ramito siyā.",
  "english": "Sitting alone, sleeping alone,\ntirelessly wandering alone;\none who tames themselves alone\nwould delight within a forest."
 },
 {
  "num": 306,
  "pali": "Abhūtavādī nirayaṁ upeti,\nYo vāpi katvā na karomi cāha;\nUbhopi te pecca samā bhavanti,\nNihīnakammā manujā parattha.",
  "english": "A liar goes to hell,\nas does one who denies what they did.\nBoth are equal in the hereafter,\nthose men of base deeds."
 },
 {
  "num": 307,
  "pali": "Kāsāvakaṇṭhā bahavo,\npāpadhammā asaññatā;\nPāpā pāpehi kammehi,\nnirayaṁ te upapajjare.",
  "english": "Many who wear a scrap of ocher cloth\nare unrestrained and wicked.\nBeing wicked, they are reborn in hell\ndue to their bad deeds."
 },
 {
  "num": 308,
  "pali": "Seyyo ayoguḷo bhutto,\ntatto aggisikhūpamo;\nYañce bhuñjeyya dussīlo,\nraṭṭhapiṇḍamasaññato.",
  "english": "It’d be better for the immoral and unrestrained\nto eat an iron ball,\nscorching, like a burning flame,\nthan to eat the nation’s alms."
 },
 {
  "num": 309,
  "pali": "Cattāri ṭhānāni naro pamatto,\nĀpajjati paradārūpasevī;\nApuññalābhaṁ na nikāmaseyyaṁ,\nNindaṁ tatīyaṁ nirayaṁ catutthaṁ.",
  "english": "Four things befall a heedless man\nwho sleeps with another’s wife:\nwickedness, poor sleep,\nill-repute, and rebirth in hell."
 },
 {
  "num": 310,
  "pali": "Apuññalābho ca gatī ca pāpikā,\nBhītassa bhītāya ratī ca thokikā;\nRājā ca daṇḍaṁ garukaṁ paṇeti,\nTasmā naro paradāraṁ na seve.",
  "english": "He accrues wickedness and is reborn in a bad place,\nall so a frightened couple <j>may snatch a moment’s pleasure,\nfor which rulers impose a heavy punishment.\nThat’s why a man should not <j>sleep with another’s wife."
 },
 {
  "num": 311,
  "pali": "Kuso yathā duggahito,\nhatthamevānukantati;\nSāmaññaṁ dupparāmaṭṭhaṁ,\nnirayāyupakaḍḍhati.",
  "english": "When kusa grass is wrongly grasped\nit only cuts the hand.\nSo too, the ascetic life, when wrongly taken,\ndrags you to hell."
 },
 {
  "num": 312,
  "pali": "Yaṁ kiñci sithilaṁ kammaṁ,\nsaṅkiliṭṭhañca yaṁ vataṁ;\nSaṅkassaraṁ brahmacariyaṁ,\nna taṁ hoti mahapphalaṁ.",
  "english": "Any lax act,\nany corrupt observance,\nor suspicious spiritual life,\nis not very fruitful."
 },
 {
  "num": 313,
  "pali": "Kayirā ce kayirāthenaṁ,\ndaḷhamenaṁ parakkame;\nSithilo hi paribbājo,\nbhiyyo ākirate rajaṁ.",
  "english": "If one is to do what should be done,\none should staunchly strive.\nFor the life gone forth when laxly led\njust stirs up dust all the more."
 },
 {
  "num": 314,
  "pali": "Akataṁ dukkaṭaṁ seyyo,\npacchā tappati dukkaṭaṁ;\nKatañca sukataṁ seyyo,\nyaṁ katvā nānutappati.",
  "english": "A bad deed is better left undone,\nfor it will plague you later on.\nA good deed is better done,\none that does not plague you."
 },
 {
  "num": 315,
  "pali": "Nagaraṁ yathā paccantaṁ,\nguttaṁ santarabāhiraṁ;\nEvaṁ gopetha attānaṁ,\nkhaṇo vo mā upaccagā;\nKhaṇātītā hi socanti,\nnirayamhi samappitā.",
  "english": "As a frontier city\nis guarded inside and out,\nso you should ward yourselves—\ndon’t let the moment pass you by.\nFor if you miss your moment\nyou’ll grieve when sent to hell."
 },
 {
  "num": 316,
  "pali": "Alajjitāye lajjanti,\nlajjitāye na lajjare;\nMicchādiṭṭhisamādānā,\nsattā gacchanti duggatiṁ.",
  "english": "Unashamed of what is shameful,\nashamed of what is not shameful;\nbeings who uphold wrong view\ngo to a bad place."
 },
 {
  "num": 317,
  "pali": "Abhaye bhayadassino,\nbhaye cābhayadassino;\nMicchādiṭṭhisamādānā,\nsattā gacchanti duggatiṁ.",
  "english": "Seeing danger where there is none,\nand blind to the actual danger,\nbeings who uphold wrong view\ngo to a bad place."
 },
 {
  "num": 318,
  "pali": "Avajje vajjamatino,\nvajje cāvajjadassino;\nMicchādiṭṭhisamādānā,\nsattā gacchanti duggatiṁ.",
  "english": "Seeing fault where there is none,\nand blind to the actual fault,\nbeings who uphold wrong view\ngo to a bad place."
 },
 {
  "num": 319,
  "pali": "Vajjañca vajjato ñatvā,\navajjañca avajjato;\nSammādiṭṭhisamādānā,\nsattā gacchanti suggatiṁ.",
  "english": "Knowing a fault as a fault\nand the faultless as faultless,\nbeings who uphold right view\ngo to a good place."
 },
 {
  "num": 320,
  "pali": "Ahaṁ nāgova saṅgāme,\ncāpato patitaṁ saraṁ;\nAtivākyaṁ titikkhissaṁ,\ndussīlo hi bahujjano.",
  "english": "Like an elephant struck\nwith arrows in battle,\nI shall endure abuse,\nfor so many folk are badly behaved."
 },
 {
  "num": 321,
  "pali": "Dantaṁ nayanti samitiṁ,\ndantaṁ rājābhirūhati;\nDanto seṭṭho manussesu,\nyotivākyaṁ titikkhati.",
  "english": "The well-tamed beast is the one led to the crowd;\nthe tamed elephant’s the one the king mounts;\nthe tamed person who endures abuse\nis the best of human beings."
 },
 {
  "num": 322,
  "pali": "Varamassatarā dantā,\nājānīyā ca sindhavā;\nKuñjarā ca mahānāgā,\nattadanto tato varaṁ.",
  "english": "Those who have tamed themselves are better\nthan fine tamed mules,\nthoroughbreds from Sindh,\nor giant tuskers."
 },
 {
  "num": 323,
  "pali": "Na hi etehi yānehi,\ngaccheyya agataṁ disaṁ;\nYathāttanā sudantena,\ndanto dantena gacchati.",
  "english": "For not on those mounts\nwould you go to the untrodden place,\nwhereas, with the help of one <j>whose self is well tamed,\nyou go there, tamed by the tamed."
 },
 {
  "num": 324,
  "pali": "Dhanapālo nāma kuñjaro,\nKaṭukabhedano dunnivārayo;\nBaddho kabaḷaṁ na bhuñjati,\nSumarati nāgavanassa kuñjaro.",
  "english": "The tusker named Dhanapāla\nis musky in rut, hard to control.\nBound, he eats not a morsel,\nfor he misses the elephant forest."
 },
 {
  "num": 325,
  "pali": "Middhī yadā hoti mahagghaso ca,\nNiddāyitā samparivattasāyī;\nMahāvarāhova nivāpapuṭṭho,\nPunappunaṁ gabbhamupeti mando.",
  "english": "One who gets drowsy from overeating,\nfond of sleep, rolling round the bed\nlike a great hog stuffed with grain:\nthat dullard returns to the womb again and again."
 },
 {
  "num": 326,
  "pali": "Idaṁ pure cittamacāri cārikaṁ,\nYenicchakaṁ yatthakāmaṁ yathāsukhaṁ;\nTadajjahaṁ niggahessāmi yoniso,\nHatthippabhinnaṁ viya aṅkusaggaho.",
  "english": "In the past my mind wandered\nhow it wished, where it liked, as it pleased.\nNow I’ll carefully guide it,\nas a trainer with a hook guides a rutting elephant."
 },
 {
  "num": 327,
  "pali": "Appamādaratā hotha,\nsacittamanurakkhatha;\nDuggā uddharathattānaṁ,\npaṅke sannova kuñjaro.",
  "english": "Delight in diligence!\nTake good care of your mind!\nPull yourself out of this pit,\nlike an elephant sunk in a bog."
 },
 {
  "num": 328,
  "pali": "Sace labhetha nipakaṁ sahāyaṁ,\nSaddhiṁ caraṁ sādhuvihāridhīraṁ;\nAbhibhuyya sabbāni parissayāni,\nCareyya tenattamano satīmā.",
  "english": "If you find an alert companion,\nan attentive friend to live happily together,\nthen, overcoming all adversities,\nwander with them, joyful and mindful."
 },
 {
  "num": 329,
  "pali": "No ce labhetha nipakaṁ sahāyaṁ,\nSaddhiṁ caraṁ sādhuvihāridhīraṁ;\nRājāva raṭṭhaṁ vijitaṁ pahāya,\nEko care mātaṅgaraññeva nāgo.",
  "english": "If you find no alert companion,\nno attentive friend to live happily together,\nthen, like a king who flees his conquered realm,\nwander alone like a tusker in the wilds."
 },
 {
  "num": 330,
  "pali": "Ekassa caritaṁ seyyo,\nNatthi bāle sahāyatā;\nEko care na ca pāpāni kayirā,\nAppossukko mātaṅgaraññeva nāgo.",
  "english": "It’s better to wander alone,\nthere’s no fellowship with fools.\nWander alone and do no wrong,\nat ease like a tusker in the wilds."
 },
 {
  "num": 331,
  "pali": "Atthamhi jātamhi sukhā sahāyā,\nTuṭṭhī sukhā yā itarītarena;\nPuññaṁ sukhaṁ jīvitasaṅkhayamhi,\nSabbassa dukkhassa sukhaṁ pahānaṁ.",
  "english": "A friend in need is a blessing;\nit’s a blessing to be content with whatever;\ngood deeds are a blessing at the end of life,\nand giving up all suffering is a blessing."
 },
 {
  "num": 332,
  "pali": "Sukhā matteyyatā loke,\natho petteyyatā sukhā;\nSukhā sāmaññatā loke,\natho brahmaññatā sukhā.",
  "english": "In this world it’s a blessing to serve\none’s mother and one’s father.\nAnd it’s a blessing also to serve\nascetics and brahmins."
 },
 {
  "num": 333,
  "pali": "Sukhaṁ yāva jarā sīlaṁ,\nsukhā saddhā patiṭṭhitā;\nSukho paññāya paṭilābho,\npāpānaṁ akaraṇaṁ sukhaṁ.",
  "english": "It’s a blessing to keep precepts until you grow old;\na blessing to be grounded in faith;\nthe getting of wisdom’s a blessing;\nand it’s a blessing to avoid doing wrong."
 },
 {
  "num": 334,
  "pali": "Manujassa pamattacārino,\nTaṇhā vaḍḍhati māluvā viya;\nSo plavatī hurā huraṁ,\nPhalamicchaṁva vanasmi vānaro.",
  "english": "When a man lives heedlessly,\ncraving grows in them like a camel’s foot creeper.\nThey jump from one thing to the next, like a langur\ngreedy for fruit in a forest grove."
 },
 {
  "num": 335,
  "pali": "Yaṁ esā sahate jammī,\ntaṇhā loke visattikā;\nSokā tassa pavaḍḍhanti,\nabhivaṭṭhaṁva bīraṇaṁ.",
  "english": "Whoever is beaten by this wretched craving,\nthis attachment to the world,\ntheir sorrow grows,\nlike grass in the rain."
 },
 {
  "num": 336,
  "pali": "Yo cetaṁ sahate jammiṁ,\ntaṇhaṁ loke duraccayaṁ;\nSokā tamhā papatanti,\nudabinduva pokkharā.",
  "english": "But whoever prevails over this wretched craving,\nso hard to get over in the world,\ntheir sorrows fall from them,\nlike a drop from a lotus-leaf."
 },
 {
  "num": 337,
  "pali": "Taṁ vo vadāmi bhaddaṁ vo,\nyāvantettha samāgatā;\nTaṇhāya mūlaṁ khaṇatha,\nusīratthova bīraṇaṁ;\nMā vo naḷaṁva sotova,\nmāro bhañji punappunaṁ.",
  "english": "I say this to you, good people,\nall those who have gathered here:\ndig up the root of craving,\nas you’d dig up grass in search of roots.\nDon’t let Māra break you again and again,\nlike a stream breaking a reed."
 },
 {
  "num": 338,
  "pali": "Yathāpi mūle anupaddave daḷhe,\nChinnopi rukkho punareva rūhati;\nEvampi taṇhānusaye anūhate,\nNibbattatī dukkhamidaṁ punappunaṁ.",
  "english": "A tree grows back even when cut down,\nso long as its roots are strong and undamaged;\nsuffering springs up again and again,\nso long as the tendency to craving is not pulled out."
 },
 {
  "num": 339,
  "pali": "Yassa chattiṁsati sotā,\nmanāpasavanā bhusā;\nMahāvahanti duddiṭṭhiṁ,\nsaṅkappā rāganissitā.",
  "english": "A person of low views\nin whom the thirty-six streams\nthat flow to pleasure are mighty,\nis swept away by lustful thoughts."
 },
 {
  "num": 340,
  "pali": "Savanti sabbadhi sotā,\nlatā uppajja tiṭṭhati;\nTañca disvā lataṁ jātaṁ,\nmūlaṁ paññāya chindatha.",
  "english": "The streams flow everywhere;\na weed springs up and remains.\nSeeing this weed that has been born,\ncut the root with wisdom."
 },
 {
  "num": 341,
  "pali": "Saritāni sinehitāni ca,\nSomanassāni bhavanti jantuno;\nTe sātasitā sukhesino,\nTe ve jātijarūpagā narā.",
  "english": "A personage’s joys\nflow from senses and cravings.\nSeekers of happiness, bent on pleasure,\ncontinue to be reborn and grow old."
 },
 {
  "num": 342,
  "pali": "Tasiṇāya purakkhatā pajā,\nParisappanti sasova bandhito;\nSaṁyojanasaṅgasattakā,\nDukkhamupenti punappunaṁ cirāya.",
  "english": "People governed by thirst,\ncrawl about like a trapped rabbit.\nBound and fettered, for a long time\nthey return to pain time and again."
 },
 {
  "num": 343,
  "pali": "Tasiṇāya purakkhatā pajā,\nParisappanti sasova bandhito;\nTasmā tasiṇaṁ vinodaye,\nĀkaṅkhanta virāgamattano.",
  "english": "People governed by thirst,\ncrawl about like a trapped rabbit.\nThat’s why one who longs for dispassion\nshould dispel thirst."
 },
 {
  "num": 344,
  "pali": "Yo nibbanatho vanādhimutto,\nVanamutto vanameva dhāvati;\nTaṁ puggalametha passatha,\nMutto bandhanameva dhāvati.",
  "english": "Unsnarled, they set out for the jungle,\nthen they run right back to the jungle they left behind.\nJust look at this individual!\nFreed, they run to bondage."
 },
 {
  "num": 345,
  "pali": "Na taṁ daḷhaṁ bandhanamāhu dhīrā,\nYadāyasaṁ dārujapabbajañca;\nSārattarattā maṇikuṇḍalesu,\nPuttesu dāresu ca yā apekkhā.",
  "english": "The attentive say that shackle is not strong\nthat’s made of iron, wood, or knots.\nBut obsession with jeweled earrings,\nconcern for your partners and children:"
 },
 {
  "num": 346,
  "pali": "Etaṁ daḷhaṁ bandhanamāhu dhīrā,\nOhārinaṁ sithilaṁ duppamuñcaṁ;\nEtampi chetvāna paribbajanti,\nAnapekkhino kāmasukhaṁ pahāya.",
  "english": "this, say the attentive, is a strong shackle\ndragging the indulgent down, hard to escape.\nHaving cut this one too they go forth,\nunconcerned, having given up sensual pleasures."
 },
 {
  "num": 347,
  "pali": "Ye rāgarattānupatanti sotaṁ,\nSayaṅkataṁ makkaṭakova jālaṁ;\nEtampi chetvāna vajanti dhīrā,\nAnapekkhino sabbadukkhaṁ pahāya.",
  "english": "Besotted by lust they fall into the stream,\nlike a spider caught in the web she wove.\nThe attentive proceed, having cut this one too,\nunconcerned, having given up all suffering."
 },
 {
  "num": 348,
  "pali": "Muñca pure muñca pacchato,\nMajjhe muñca bhavassa pāragū;\nSabbattha vimuttamānaso,\nNa punaṁ jātijaraṁ upehisi.",
  "english": "Let go of the past, let go of the future,\nlet go of the present, having gone beyond rebirth.\nWith your heart freed in every respect,\nyou’ll not come again to rebirth and old age."
 },
 {
  "num": 349,
  "pali": "Vitakkamathitassa jantuno,\nTibbarāgassa subhānupassino;\nBhiyyo taṇhā pavaḍḍhati,\nEsa kho daḷhaṁ karoti bandhanaṁ.",
  "english": "For a personage churned by thoughts,\nvery lustful, focusing on beauty,\ntheir craving grows and grows,\ntying them with a stout bond."
 },
 {
  "num": 350,
  "pali": "Vitakkūpasame ca yo rato,\nAsubhaṁ bhāvayate sadā sato;\nEsa kho byanti kāhiti,\nEsa checchati mārabandhanaṁ.",
  "english": "But one who loves to calm their thoughts,\ndeveloping perception of ugliness, ever mindful,\nwill surely eliminate that craving,\ncutting off the bonds of Māra."
 },
 {
  "num": 351,
  "pali": "Niṭṭhaṅgato asantāsī,\nvītataṇho anaṅgaṇo;\nAcchindi bhavasallāni,\nantimoyaṁ samussayo.",
  "english": "One who is confident, unafraid,\nrid of craving, free of blemish,\nhaving struck down the arrows flying to future lives,\nthis bag of bones is their last."
 },
 {
  "num": 352,
  "pali": "Vītataṇho anādāno,\nNiruttipadakovido;\nAkkharānaṁ sannipātaṁ,\nJaññā pubbāparāni ca;\nSa ve “antimasārīro,\nMahāpañño mahāpuriso”ti vuccati.",
  "english": "Rid of craving, free of grasping,\nexpert in the definition of terms,\nknowing the correct\nstructure and sequence of syllables,\nthey are said to be one who bears their final body,\none of great wisdom, a great person."
 },
 {
  "num": 353,
  "pali": "Sabbābhibhū sabbavidūhamasmi,\nSabbesu dhammesu anūpalitto;\nSabbañjaho taṇhakkhaye vimutto,\nSayaṁ abhiññāya kamuddiseyyaṁ.",
  "english": "I am the vanquisher of all, the knower of all,\nunsullied in the midst of all things.\nI’ve given up all, freed in the ending of craving.\nSince I know for myself, whose follower should I be?"
 },
 {
  "num": 354,
  "pali": "Sabbadānaṁ dhammadānaṁ jināti,\nSabbarasaṁ dhammaraso jināti;\nSabbaratiṁ dhammarati jināti,\nTaṇhakkhayo sabbadukkhaṁ jināti.",
  "english": "The gift of the teaching surmounts all other gifts;\nthe taste of the teaching surmounts all other tastes;\nthe joy of the teaching surmounts all other joys;\nthe ending of craving surmounts all suffering."
 },
 {
  "num": 355,
  "pali": "Hananti bhogā dummedhaṁ,\nno ca pāragavesino;\nBhogataṇhāya dummedho,\nhanti aññeva attanaṁ.",
  "english": "Riches ruin a simpleton,\nbut not a seeker of the far shore.\nFrom craving for wealth, a simpleton\nruins themselves and others."
 },
 {
  "num": 356,
  "pali": "Tiṇadosāni khettāni,\nrāgadosā ayaṁ pajā;\nTasmā hi vītarāgesu,\ndinnaṁ hoti mahapphalaṁ.",
  "english": "Weeds are the bane of crops,\nbut greed is these folk’s bane.\nThat’s why a gift to one rid of greed\nis so very fruitful."
 },
 {
  "num": 357,
  "pali": "Tiṇadosāni khettāni,\ndosadosā ayaṁ pajā;\nTasmā hi vītadosesu,\ndinnaṁ hoti mahapphalaṁ.",
  "english": "Weeds are the bane of crops,\nbut hate is these folk’s bane.\nThat’s why a gift to one rid of hate\nis so very fruitful."
 },
 {
  "num": 358,
  "pali": "Tiṇadosāni khettāni,\nmohadosā ayaṁ pajā;\nTasmā hi vītamohesu,\ndinnaṁ hoti mahapphalaṁ.",
  "english": "Weeds are the bane of crops,\nbut delusion is these folk’s bane.\nThat’s why a gift to one rid of delusion\nis so very fruitful."
 },
 {
  "num": 359,
  "pali": "Tiṇadosāni khettāni,\nicchādosā ayaṁ pajā;\nTasmā hi vigaticchesu,\ndinnaṁ hoti mahapphalaṁ.",
  "english": "Weeds are the bane of crops,\nbut desire is these folk’s bane.\nThat’s why a gift to one rid of desire\nis so very fruitful."
 },
 {
  "num": 360,
  "pali": "Cakkhunā saṁvaro sādhu,\nsādhu sotena saṁvaro;\nGhānena saṁvaro sādhu,\nsādhu jivhāya saṁvaro.",
  "english": "Restraint of the eye is good;\ngood is restraint of the ear;\nrestraint of the nose is good;\ngood is restraint of the tongue."
 },
 {
  "num": 361,
  "pali": "Kāyena saṁvaro sādhu,\nsādhu vācāya saṁvaro;\nManasā saṁvaro sādhu,\nsādhu sabbattha saṁvaro;\nSabbattha saṁvuto bhikkhu,\nsabbadukkhā pamuccati.",
  "english": "Restraint of the body is good;\ngood is restraint of speech;\nrestraint of mind is good;\neverywhere, restraint is good.\nThe mendicant restrained everywhere\nis released from all suffering."
 },
 {
  "num": 362,
  "pali": "Hatthasaṁyato pādasaṁyato,\nVācāsaṁyato saṁyatuttamo;\nAjjhattarato samāhito,\nEko santusito tamāhu bhikkhuṁ.",
  "english": "One restrained in hand and foot,\nand in speech, the supreme restraint;\nhappy inside, serene,\nsolitary, content, I call a mendicant."
 },
 {
  "num": 363,
  "pali": "Yo mukhasaṁyato bhikkhu,\nmantabhāṇī anuddhato;\nAtthaṁ dhammañca dīpeti,\nmadhuraṁ tassa bhāsitaṁ.",
  "english": "When a mendicant of restrained mouth,\nthoughtful in counsel, not restless,\nexplains the text and its meaning,\ntheir words are sweet."
 },
 {
  "num": 364,
  "pali": "Dhammārāmo dhammarato,\ndhammaṁ anuvicintayaṁ;\nDhammaṁ anussaraṁ bhikkhu,\nsaddhammā na parihāyati.",
  "english": "Delighting in the teaching, enjoying the teaching,\ncontemplating the teaching,\na mendicant who recollects the teaching\ndoesn’t fall away from the true teaching."
 },
 {
  "num": 365,
  "pali": "Salābhaṁ nātimaññeyya,\nnāññesaṁ pihayaṁ care;\nAññesaṁ pihayaṁ bhikkhu,\nsamādhiṁ nādhigacchati.",
  "english": "A well-off mendicant ought not look down\non others, nor should they be envious.\nA mendicant who envies others\ndoes not achieve immersion."
 },
 {
  "num": 366,
  "pali": "Appalābhopi ce bhikkhu,\nsalābhaṁ nātimaññati;\nTaṁ ve devā pasaṁsanti,\nsuddhājīviṁ atanditaṁ.",
  "english": "If a mendicant is poor in offerings,\nthe well-to-do ought not look down on them.\nFor the gods indeed praise them,\nwho are tireless and pure of livelihood."
 },
 {
  "num": 367,
  "pali": "Sabbaso nāmarūpasmiṁ,\nyassa natthi mamāyitaṁ;\nAsatā ca na socati,\nsa ve “bhikkhū”ti vuccati.",
  "english": "One who has no sense of ownership\nin the whole realm of name and form,\nwho does not grieve for that which is not,\nis said to be a mendicant."
 },
 {
  "num": 368,
  "pali": "Mettāvihārī yo bhikkhu,\npasanno buddhasāsane;\nAdhigacche padaṁ santaṁ,\nsaṅkhārūpasamaṁ sukhaṁ.",
  "english": "A mendicant who meditates on love,\ndevoted to the Buddha’s teaching,\nwould realize the peaceful state,\nthe blissful stilling of conditions."
 },
 {
  "num": 369,
  "pali": "Siñca bhikkhu imaṁ nāvaṁ,\nsittā te lahumessati;\nChetvā rāgañca dosañca,\ntato nibbānamehisi.",
  "english": "Bail out this boat, mendicant!\nWhen bailed out it will float lightly.\nHaving cut off desire and hate,\nyou shall reach extinguishment."
 },
 {
  "num": 370,
  "pali": "Pañca chinde pañca jahe,\npañca cuttari bhāvaye;\nPañca saṅgātigo bhikkhu,\n“oghatiṇṇo”ti vuccati.",
  "english": "Five to cut, five to drop,\nand five more to develop.\nWhen a mendicant slips five chains\nthey’re said to have crossed the flood."
 },
 {
  "num": 371,
  "pali": "Jhāya bhikkhu mā pamādo,\nMā te kāmaguṇe ramessu cittaṁ;\nMā lohaguḷaṁ gilī pamatto,\nMā kandi “dukkhamidan”ti dayhamāno.",
  "english": "Practice absorption, don’t be negligent!\nDon’t let the mind delight in the senses!\nDon’t heedlessly swallow a hot iron ball!\nAnd when it burns, don’t cry, “Oh, the pain!”"
 },
 {
  "num": 372,
  "pali": "Natthi jhānaṁ apaññassa,\npaññā natthi ajhāyato;\nYamhi jhānañca paññā ca,\nsa ve nibbānasantike.",
  "english": "No absorption for one without wisdom,\nno wisdom for one without absorption.\nBut one with absorption and wisdom—\nthey have truly drawn near to extinguishment."
 },
 {
  "num": 373,
  "pali": "Suññāgāraṁ paviṭṭhassa,\nsantacittassa bhikkhuno;\nAmānusī rati hoti,\nsammā dhammaṁ vipassato.",
  "english": "A mendicant who enters an empty hut\nwith mind at peace\nfinds a superhuman delight\nas they rightly discern the Dhamma."
 },
 {
  "num": 374,
  "pali": "Yato yato sammasati,\nkhandhānaṁ udayabbayaṁ;\nLabhatī pītipāmojjaṁ,\namataṁ taṁ vijānataṁ.",
  "english": "Whenever they are mindful\nof the rise and fall of the aggregates,\nthey feel rapture and joy:\nthat is freedom from death for one who knows."
 },
 {
  "num": 375,
  "pali": "Tatrāyamādi bhavati,\nidha paññassa bhikkhuno;\nIndriyagutti santuṭṭhi,\npātimokkhe ca saṁvaro.",
  "english": "This is the very start of the path\nfor a wise mendicant here:\nguarding the senses, contentment,\nand restraint in the monastic code."
 },
 {
  "num": 376,
  "pali": "Mitte bhajassu kalyāṇe,\nsuddhājīve atandite;\nPaṭisanthāravutyassa,\nācārakusalo siyā;\nTato pāmojjabahulo,\ndukkhassantaṁ karissati.",
  "english": "Mix with spiritual friends,\nwho are tireless and pure of livelihood.\nShare what you have with others,\nbeing skillful in your conduct.\nAnd when you’re full of joy,\nyou’ll make an end to suffering."
 },
 {
  "num": 377,
  "pali": "Vassikā viya pupphāni,\nmaddavāni pamuñcati;\nEvaṁ rāgañca dosañca,\nvippamuñcetha bhikkhavo.",
  "english": "As a jasmine sheds\nits withered flowers,\nO mendicants,\nshed greed and hate."
 },
 {
  "num": 378,
  "pali": "Santakāyo santavāco,\nsantavā susamāhito;\nVantalokāmiso bhikkhu,\n“upasanto”ti vuccati.",
  "english": "Calm in body, calm in speech,\npeaceful and serene;\na mendicant who’s spat out the world’s bait\nis said to be one at peace."
 },
 {
  "num": 379,
  "pali": "Attanā codayattānaṁ,\npaṭimaṁsetha attanā;\nSo attagutto satimā,\nsukhaṁ bhikkhu vihāhisi.",
  "english": "Urge yourself on,\nreflect on yourself.\nA mendicant self-controlled and mindful\nwill always dwell in happiness."
 },
 {
  "num": 380,
  "pali": "Attā hi attano nātho,\nko hi nātho paro siyā;\nAttā hi attano gati,\ntasmā saṁyamamattānaṁ;\nAssaṁ bhadraṁva vāṇijo.",
  "english": "Self is indeed the lord of self,\nfor who else would be one’s lord?\nSelf is indeed the home of self,\nso restrain yourself,\nas a merchant his thoroughbred steed."
 },
 {
  "num": 381,
  "pali": "Pāmojjabahulo bhikkhu,\npasanno buddhasāsane;\nAdhigacche padaṁ santaṁ,\nsaṅkhārūpasamaṁ sukhaṁ.",
  "english": "A monk full of joy\ntrusting in the Buddha’s teaching,\nwould realize the peaceful state,\nthe blissful stilling of conditions."
 },
 {
  "num": 382,
  "pali": "Yo have daharo bhikkhu,\nyuñjati buddhasāsane;\nSomaṁ lokaṁ pabhāseti,\nabbhā muttova candimā.",
  "english": "A young mendicant\ndevoted to the Buddha’s teaching,\nshines upon this world,\nlike the moon freed from clouds."
 },
 {
  "num": 383,
  "pali": "Chinda sotaṁ parakkamma,\nkāme panuda brāhmaṇa;\nSaṅkhārānaṁ khayaṁ ñatvā,\nakataññūsi brāhmaṇa.",
  "english": "Cut the stream, striving!\nCast aside sensual pleasures, brahmin.\nKnowing the ending of conditions,\nknow the uncreated, brahmin."
 },
 {
  "num": 384,
  "pali": "Yadā dvayesu dhammesu,\npāragū hoti brāhmaṇo;\nAthassa sabbe saṁyogā,\natthaṁ gacchanti jānato.",
  "english": "When a brahmin has gone beyond\ndualistic phenomena,\nthen they consciously\nmake an end of all fetters."
 },
 {
  "num": 385,
  "pali": "Yassa pāraṁ apāraṁ vā,\npārāpāraṁ na vijjati;\nVītaddaraṁ visaṁyuttaṁ,\ntamahaṁ brūmi brāhmaṇaṁ.",
  "english": "One for whom there is no crossing over\nor crossing back, or crossing over and back;\nstress-free, detached,\nthat’s who I declare a brahmin."
 },
 {
  "num": 386,
  "pali": "Jhāyiṁ virajamāsīnaṁ,\nkatakiccamanāsavaṁ;\nUttamatthamanuppattaṁ,\ntamahaṁ brūmi brāhmaṇaṁ.",
  "english": "Absorbed, rid of hopes,\ntheir task completed, without defilements,\narrived at the highest goal:\nthat’s who I declare a brahmin."
 },
 {
  "num": 387,
  "pali": "Divā tapati ādicco,\nrattimābhāti candimā;\nSannaddho khattiyo tapati,\njhāyī tapati brāhmaṇo;\nAtha sabbamahorattiṁ,\nbuddho tapati tejasā.",
  "english": "The sun blazes by day,\nthe moon radiates at night,\nthe aristocrat shines in armor,\nand the brahmin shines in absorption.\nBut all day and all night,\nthe Buddha blazes with glory."
 },
 {
  "num": 388,
  "pali": "Bāhitapāpoti brāhmaṇo,\nSamacariyā samaṇoti vuccati;\nPabbājayamattano malaṁ,\nTasmā “pabbajito”ti vuccati.",
  "english": "A brahmin’s so-called <j>since they’ve banished evil,\nan ascetic’s so-called <j>since they live a serene life.\nOne who has renounced all stains\nis said to be a “renunciant”."
 },
 {
  "num": 389,
  "pali": "Na brāhmaṇassa pahareyya,\nnāssa muñcetha brāhmaṇo;\nDhī brāhmaṇassa hantāraṁ,\ntato dhī yassa muñcati.",
  "english": "One should never strike a brahmin,\nnor should a brahmin retaliate.\nWoe to the one who hurts a brahmin,\nand woe for the one who retaliates."
 },
 {
  "num": 390,
  "pali": "Na brāhmaṇassetadakiñci seyyo,\nYadā nisedho manaso piyehi;\nYato yato hiṁsamano nivattati,\nTato tato sammatimeva dukkhaṁ.",
  "english": "Nothing is better for a brahmin\nthan to hold their mind back from attachment.\nFrom wherever a cruel wish recoils,\nright there suffering subsides."
 },
 {
  "num": 391,
  "pali": "Yassa kāyena vācāya,\nmanasā natthi dukkaṭaṁ;\nSaṁvutaṁ tīhi ṭhānehi,\ntamahaṁ brūmi brāhmaṇaṁ.",
  "english": "Who does nothing wrong\nby body, speech or mind,\nrestrained in these three respects,\nthat’s who I declare a brahmin."
 },
 {
  "num": 392,
  "pali": "Yamhā dhammaṁ vijāneyya,\nsammāsambuddhadesitaṁ;\nSakkaccaṁ taṁ namasseyya,\naggihuttaṁva brāhmaṇo.",
  "english": "You should graciously honor\nthe one from whom you learn the Dhamma\ntaught by the awakened Buddha,\nas a brahmin honors the sacred flame."
 },
 {
  "num": 393,
  "pali": "Na jaṭāhi na gottena,\nna jaccā hoti brāhmaṇo;\nYamhi saccañca dhammo ca,\nso sucī so ca brāhmaṇo.",
  "english": "Not by matted hair or family,\nor birth is one a brahmin.\nThose who are  truthful and principled:\nthey are pure, they are brahmins."
 },
 {
  "num": 394,
  "pali": "Kiṁ te jaṭāhi dummedha,\nkiṁ te ajinasāṭiyā;\nAbbhantaraṁ te gahanaṁ,\nbāhiraṁ parimajjasi.",
  "english": "Why the matted hair, you simpleton,\nand why the skin of deer?\nThe tangle is inside you,\nyet you polish up your outsides."
 },
 {
  "num": 395,
  "pali": "Paṁsukūladharaṁ jantuṁ,\nkisaṁ dhamanisanthataṁ;\nEkaṁ vanasmiṁ jhāyantaṁ,\ntamahaṁ brūmi brāhmaṇaṁ.",
  "english": "A personage who wears robes of rags,\nlean, their limbs showing veins,\nmeditating alone in the forest,\nthat’s who I declare a brahmin."
 },
 {
  "num": 396,
  "pali": "Na cāhaṁ brāhmaṇaṁ brūmi,\nyonijaṁ mattisambhavaṁ;\nBhovādi nāma so hoti,\nsace hoti sakiñcano;\nAkiñcanaṁ anādānaṁ,\ntamahaṁ brūmi brāhmaṇaṁ.",
  "english": "I don’t call someone a brahmin\nafter the mother’s womb they’re born from.\nIf they still have attachments,\nthey’re just someone who says “worthy”.\nHaving nothing, taking nothing:\nthat’s who I declare a brahmin."
 },
 {
  "num": 397,
  "pali": "Sabbasaṁyojanaṁ chetvā,\nyo ve na paritassati;\nSaṅgātigaṁ visaṁyuttaṁ,\ntamahaṁ brūmi brāhmaṇaṁ.",
  "english": "Having cut off all fetters\nthey have no anxiety.\nThey’ve slipped their chains and are detached:\nthat’s who I declare a brahmin."
 },
 {
  "num": 398,
  "pali": "Chetvā naddhiṁ varattañca,\nsandānaṁ sahanukkamaṁ;\nUkkhittapalighaṁ buddhaṁ,\ntamahaṁ brūmi brāhmaṇaṁ.",
  "english": "They’ve cut the strap and harness,\nthe halter and bridle too,\nwith cross-bar lifted, they’re awakened:\nthat’s who I declare a brahmin."
 },
 {
  "num": 399,
  "pali": "Akkosaṁ vadhabandhañca,\naduṭṭho yo titikkhati;\nKhantībalaṁ balānīkaṁ,\ntamahaṁ brūmi brāhmaṇaṁ.",
  "english": "Abuse, killing, caging:\nthey endure these without anger.\nPatience is their powerful army:\nthat’s who I declare a brahmin."
 },
 {
  "num": 400,
  "pali": "Akkodhanaṁ vatavantaṁ,\nsīlavantaṁ anussadaṁ;\nDantaṁ antimasārīraṁ,\ntamahaṁ brūmi brāhmaṇaṁ.",
  "english": "Not irritable or pretentious,\ndutiful in precepts and observances,\ntamed, bearing their final body:\nthat’s who I declare a brahmin."
 },
 {
  "num": 401,
  "pali": "Vāri pokkharapatteva,\nāraggeriva sāsapo;\nYo na limpati kāmesu,\ntamahaṁ brūmi brāhmaṇaṁ.",
  "english": "Like water from a lotus leaf,\nlike a mustard seed off the point of a pin,\nsensual pleasures slip off them:\nthat’s who I declare a brahmin."
 },
 {
  "num": 402,
  "pali": "Yo dukkhassa pajānāti,\nidheva khayamattano;\nPannabhāraṁ visaṁyuttaṁ,\ntamahaṁ brūmi brāhmaṇaṁ.",
  "english": "They understand for themselves\nthe end of suffering in this life;\nwith burden put down, detached:\nthat’s who I declare a brahmin."
 },
 {
  "num": 403,
  "pali": "Gambhīrapaññaṁ medhāviṁ,\nmaggāmaggassa kovidaṁ;\nUttamatthamanuppattaṁ,\ntamahaṁ brūmi brāhmaṇaṁ.",
  "english": "Deep in wisdom, intelligent,\nexpert in the path and what is not the path;\narrived at the highest goal:\nthat’s who I declare a brahmin."
 },
 {
  "num": 404,
  "pali": "Asaṁsaṭṭhaṁ gahaṭṭhehi,\nanāgārehi cūbhayaṁ;\nAnokasārimappicchaṁ,\ntamahaṁ brūmi brāhmaṇaṁ.",
  "english": "Mixing with neither\nhouseholders nor the homeless;\na migrant with no bastion, few in wishes:\nthat’s who I declare a brahmin."
 },
 {
  "num": 405,
  "pali": "Nidhāya daṇḍaṁ bhūtesu,\ntasesu thāvaresu ca;\nYo na hanti na ghāteti,\ntamahaṁ brūmi brāhmaṇaṁ.",
  "english": "They’ve laid aside violence\nagainst creatures firm and frail;\nnot killing or making others kill:\nthat’s who I declare a brahmin."
 },
 {
  "num": 406,
  "pali": "Aviruddhaṁ viruddhesu,\nattadaṇḍesu nibbutaṁ;\nSādānesu anādānaṁ,\ntamahaṁ brūmi brāhmaṇaṁ.",
  "english": "Not fighting among those who fight,\nquenched among those who have taken up arms,\nnot grasping among those who grasp:\nthat’s who I declare a brahmin."
 },
 {
  "num": 407,
  "pali": "Yassa rāgo ca doso ca,\nmāno makkho ca pātito;\nSāsaporiva āraggā,\ntamahaṁ brūmi brāhmaṇaṁ.",
  "english": "They’ve discarded greed and hate,\nalong with conceit and contempt,\nlike a mustard seed off the point of a pin:\nthat’s who I declare a brahmin."
 },
 {
  "num": 408,
  "pali": "Akakkasaṁ viññāpaniṁ,\ngiraṁ saccamudīraye;\nYāya nābhisaje kañci,\ntamahaṁ brūmi brāhmaṇaṁ.",
  "english": "The words they utter\nare polished, informative, and true,\nand don’t offend anyone:\nthat’s who I declare a brahmin."
 },
 {
  "num": 409,
  "pali": "Yodha dīghaṁ va rassaṁ vā,\naṇuṁ thūlaṁ subhāsubhaṁ;\nLoke adinnaṁ nādiyati,\ntamahaṁ brūmi brāhmaṇaṁ.",
  "english": "They don’t steal anything in the world,\nlong or short,\ntiny or huge, beautiful or ugly:\nthat’s who I declare a brahmin."
 },
 {
  "num": 410,
  "pali": "Āsā yassa na vijjanti,\nasmiṁ loke paramhi ca;\nNirāsāsaṁ visaṁyuttaṁ,\ntamahaṁ brūmi brāhmaṇaṁ.",
  "english": "They have no hope\nin this world or the next;\nwith no need for hope, detached:\nthat’s who I declare a brahmin."
 },
 {
  "num": 411,
  "pali": "Yassālayā na vijjanti,\naññāya akathaṅkathī;\nAmatogadhamanuppattaṁ,\ntamahaṁ brūmi brāhmaṇaṁ.",
  "english": "They have no clinging,\nknowledge has freed them of indecision,\nthey’ve arrived at the objective, freedom from death:\nthat’s who I declare a brahmin."
 },
 {
  "num": 412,
  "pali": "Yodha puññañca pāpañca,\nubho saṅgamupaccagā;\nAsokaṁ virajaṁ suddhaṁ,\ntamahaṁ brūmi brāhmaṇaṁ.",
  "english": "They’ve escaped the chain\nof both good and bad deeds;\nsorrowless, stainless, pure:\nthat’s who I declare a brahmin."
 },
 {
  "num": 413,
  "pali": "Candaṁva vimalaṁ suddhaṁ,\nvippasannamanāvilaṁ;\nNandībhavaparikkhīṇaṁ,\ntamahaṁ brūmi brāhmaṇaṁ.",
  "english": "Pure as the spotless moon,\nclear and unclouded,\nthey’ve ended relish for rebirth:\nthat’s who I declare a brahmin."
 },
 {
  "num": 414,
  "pali": "Yomaṁ palipathaṁ duggaṁ,\nsaṁsāraṁ mohamaccagā;\nTiṇṇo pāraṅgato jhāyī,\nanejo akathaṅkathī;\nAnupādāya nibbuto,\ntamahaṁ brūmi brāhmaṇaṁ.",
  "english": "They’ve got past this grueling swamp\nof delusion, transmigration.\nMeditating in stillness, free of indecision,\nthey have crossed over to the far shore.\nThey’re quenched by not grasping:\nthat’s who I declare a brahmin."
 },
 {
  "num": 415,
  "pali": "Yodha kāme pahantvāna,\nanāgāro paribbaje;\nKāmabhavaparikkhīṇaṁ,\ntamahaṁ brūmi brāhmaṇaṁ.",
  "english": "They’ve given up sensual pleasures,\nand have gone forth from lay life;\nthey’ve ended rebirth in the sensual realm:\nthat’s who I declare a brahmin."
 },
 {
  "num": 416,
  "pali": "Yodha taṇhaṁ pahantvāna,\nanāgāro paribbaje;\nTaṇhābhavaparikkhīṇaṁ,\ntamahaṁ brūmi brāhmaṇaṁ.\nanāgāro paribbaje;\nTaṇhābhavaparikkhīṇaṁ,\ntamahaṁ brūmi brāhmaṇaṁ.",
  "english": "They’ve given up craving,\nand have gone forth from lay life;\nthey’ve ended craving to be reborn:\nthat’s who I declare a brahmin.\nand have gone forth from lay life;\nthey’ve ended craving to be reborn:\nthat’s who I declare a brahmin."
 },
 {
  "num": 417,
  "pali": "Hitvā mānusakaṁ yogaṁ,\ndibbaṁ yogaṁ upaccagā;\nSabbayogavisaṁyuttaṁ,\ntamahaṁ brūmi brāhmaṇaṁ.",
  "english": "They’ve thrown off the human yoke,\nand slipped out of the heavenly yoke;\nunyoked from all yokes:\nthat’s who I declare a brahmin."
 },
 {
  "num": 418,
  "pali": "Hitvā ratiñca aratiñca,\nsītibhūtaṁ nirūpadhiṁ;\nSabbalokābhibhuṁ vīraṁ,\ntamahaṁ brūmi brāhmaṇaṁ.",
  "english": "Giving up desire and discontent,\nthey’re cooled and free of attachments;\na hero, master of the whole world:\nthat’s who I declare a brahmin."
 },
 {
  "num": 419,
  "pali": "Cutiṁ yo vedi sattānaṁ,\nupapattiñca sabbaso;\nAsattaṁ sugataṁ buddhaṁ,\ntamahaṁ brūmi brāhmaṇaṁ.",
  "english": "They know the passing away\nand rebirth of all beings;\nunattached, holy, awakened:\nthat’s who I declare a brahmin."
 },
 {
  "num": 420,
  "pali": "Yassa gatiṁ na jānanti,\ndevā gandhabbamānusā;\nKhīṇāsavaṁ arahantaṁ,\ntamahaṁ brūmi brāhmaṇaṁ.",
  "english": "Gods, centaurs, and humans\ndon’t know their destiny;\nthe perfected ones with defilements ended:\nthat’s who I declare a brahmin."
 },
 {
  "num": 421,
  "pali": "Yassa pure ca pacchā ca,\nmajjhe ca natthi kiñcanaṁ;\nAkiñcanaṁ anādānaṁ,\ntamahaṁ brūmi brāhmaṇaṁ.",
  "english": "They have nothing before or after,\nor even in between.\nHaving nothing, taking nothing:\nthat’s who I declare a brahmin."
 },
 {
  "num": 422,
  "pali": "Usabhaṁ pavaraṁ vīraṁ,\nmahesiṁ vijitāvinaṁ;\nAnejaṁ nhātakaṁ buddhaṁ,\ntamahaṁ brūmi brāhmaṇaṁ.",
  "english": "Captain of the herd, excellent hero,\ngreat seer and victor;\nunstirred, washed, awakened:\nthat’s who I declare a brahmin."
 },
 {
  "num": 423,
  "pali": "Pubbenivāsaṁ yo vedi,\nsaggāpāyañca passati;\nAtho jātikkhayaṁ patto,\nabhiññāvosito muni;\nSabbavositavosānaṁ,\ntamahaṁ brūmi brāhmaṇaṁ.",
  "english": "One who knows their past lives,\nsees heaven and places of loss,\nand has attained the end of rebirth;\na sage of perfect insight\nat the summit of spiritual perfection:\nthat’s who I declare a brahmin."
 }
];
